// The all-reduce over the TP ranks that ends moe's down and row_linear_ar, written for GLM-5's 6144
// rows = 256 blocks x 24: Infera-Flash's glm5/all_reduce.h for up to 16 tokens a call, a block's
// AR_ROWS x M outputs and its packets taken by its threads in turn.
#pragma once

#include "common/device.h"
#include "glm5_m16/config.h"

namespace infera_flash::glm5_m16 {

// a packet to another rank's receive buffer: system scope like store_nt, but without nt (the peer's last-level cache
// keeps the line for its poll)
__device__ inline void store_peer(uint32x4 *ptr, uint32x4 val) {
    asm volatile("global_store_dwordx4 %0, %1, off sc0 sc1\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}


// Block k of every rank swaps its share of the [M, HIDDEN_SIZE] output with block k of the others.
struct AllReduceParams {
    bfloat16       *out;        // [M, HIDDEN_SIZE]
    bool            accumulate; // out = bf16(bf16(sum) + prior), HF's residual add
    const bfloat16 *prior;      // [M, HIDDEN_SIZE] the residual
    // every rank's AR_BUFFER_SIZE receive buffer, IPC-mapped; per-block call counters. World 1
    // means no all-reduce.
    void *recv[Config::MAX_RANKS];
    int  *calls;
    int   rank;
    int   world;
};

// This block's last call number, as a vector load (a scalar one holds back the loads after it) that
// reads 0 past the end (world 1).
__device__ inline uint32_t last_call(const AllReduceParams &p) {
    return __builtin_amdgcn_raw_buffer_load_b32(
        raw_buffer(p.calls, p.world > 1 ? Config::NUM_BLOCKS * sizeof(int) : 0),
        blockIdx.x * sizeof(int), 0, 0);
}

// The row split of moe's down and row_linear_ar: block k owns output rows 24k .. 24k + 23. Blocks
// 2j and 2j + 1 share 16-row groups 3j .. 3j + 2, the even one taking group 3j and rows 0-7 of
// 3j + 1, the odd one rows 8-15 of 3j + 1 and group 3j + 2. Waves 0 and 1 take the full group,
// waves 2 and 3 the half group, each pair splitting K; in the half group lanes 8-15 repeat the rows
// of lanes 0-7 and their C rows are dropped.
static_assert(Config::AR_ROWS == 24); // the split: one 16-row group and half of another
__device__ inline int split_group(int block, int wave) {
    return block / 2 * 3 + (wave < 2 ? 2 * (block & 1) : 1);
}
__device__ inline int split_group(int wave) { return split_group(blockIdx.x, wave); }
// the row of its 16-row group this lane loads
__device__ inline int split_row(int wave, int lane) {
    return wave < 2 ? lane % 16 : lane % 8 + 8 * (blockIdx.x & 1);
}

// a block's AR_ROWS x M outputs per thread: thread t takes outputs t, t + BLOCK_SIZE, ...
template <int NUM_TOKENS>
constexpr int AR_ITEMS = (Config::AR_ROWS * NUM_TOKENS + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE;

// The residuals this thread adds in all_reduce_rows (0 without accumulate). Load them well before
// the exchange: the exchange's poll waits for every load issued before it.
template <int NUM_TOKENS>
__device__ inline void all_reduce_residual(const AllReduceParams &p,
                                           float (&prior)[AR_ITEMS<NUM_TOKENS>]) {
#pragma unroll
    for (int k = 0; k < AR_ITEMS<NUM_TOKENS>; ++k) {
        const int t = threadIdx.x + k * Config::BLOCK_SIZE;
        prior[k]    = p.accumulate && t < Config::AR_ROWS * NUM_TOKENS
                          ? static_cast<float>(p.prior[t / Config::AR_ROWS * Config::HIDDEN_SIZE +
                                                       Config::AR_ROWS * blockIdx.x + t % Config::AR_ROWS])
                          : 0.0f;
    }
}

// packet i of block `block`'s share from rank src in the receive buffer, for call's parity
__device__ __forceinline__ uint32_t ar_slot(uint32_t call, int src, int block, int i) {
    return ((call % 2 * Config::MAX_RANKS + src) * Config::NUM_BLOCKS + block) *
               Config::AR_PACKETS +
           i;
}

// all_reduce_rows' LDS
struct RowsSmem {
    floatx4  tiles[Config::BLOCK_SIZE]; // each wave's 16x16 result
    // every rank's [M][AR_ROWS] share
    bfloat16 rows[Config::MAX_RANKS][Config::AR_ROWS * Config::MAX_NUM_TOKENS];
};

// The end of down and row_linear_ar: block k's output rows from its 4 waves' 16x16 tiles, split as
// above, summed over the TP ranks, plus prior (all_reduce_residual) when accumulating. SC1: the rows
// go out in sc1 stores, for other XCDs in the same kernel.
template <int NUM_TOKENS, bool SC1 = false>
__device__ __forceinline__ void all_reduce_rows(const AllReduceParams &p, RowsSmem &s, floatx4 acc,
                                                uint32_t call,
                                                const float (&prior)[AR_ITEMS<NUM_TOKENS>]) {
    constexpr int ROWS    = Config::AR_ROWS;
    constexpr int OUTPUTS = ROWS * NUM_TOKENS;
    const int     tid     = threadIdx.x;
    const int     block   = blockIdx.x;
    const int     odd     = block & 1;
    s.tiles[tid]          = acc;
    block_sync_lds(); // loads the block no longer needs may still be in flight
#pragma unroll
    for (int k = 0; k < AR_ITEMS<NUM_TOKENS>; ++k) {
        const int t = tid + k * Config::BLOCK_SIZE;
        if (t < OUTPUTS) {
            const int m = t / ROWS;
            const int q = t % ROWS; // our output row 24k + q
            // even CUs: the full group's 16 rows, then the half group's 8; odd CUs the other way round
            const bool     full = odd ? q >= 8 : q < 16;
            const int      c    = full ? q - 8 * odd : q - 16 + 16 * odd;
            const floatx4 *tile = s.tiles + (full ? 0 : 2) * THREADS_PER_WARP + 16 * (c / 4) + m;
            s.rows[p.rank][t] =
                static_cast<bfloat16>(tile[0][c % 4] + tile[THREADS_PER_WARP][c % 4]);
        }
    }
    block_sync_lds();

    // M <= 4 (MoE runs them on this kernel too) keeps 6 outputs and the call number a packet: there the
    // exchange waits on latency, not bytes, and the zeroing costs more than the fewer packets save.
    if constexpr (NUM_TOKENS <= 4) {
        // all-reduce: block k swaps its rows with block k of every other rank, a packet 6 outputs and
        // the call number in one 16 B store, which lands whole, so a packet showing this call is
        // complete. Every packet goes out before any is awaited. Two buffers by call parity: no rank
        // gets two calls ahead
        if (p.world > 1) {
            constexpr int PACKETS = OUTPUTS / 6;
            static_assert(PACKETS * 6 == OUTPUTS && PACKETS <= Config::AR_PACKETS);
            const int sends = (p.world - 1) * PACKETS;
            for (int t = tid; t < sends; t += Config::BLOCK_SIZE) {
                const int       other = (p.rank + 1 + t / PACKETS) % p.world;
                const int       i     = t % PACKETS;
                const uint32_t *mine  = reinterpret_cast<const uint32_t *>(s.rows[p.rank]) + 3 * i;
                store_peer(static_cast<uint32x4 *>(p.recv[other]) + ar_slot(call, p.rank, block, i),
                         uint32x4{mine[0], mine[1], mine[2], call});
            }
            for (int t = tid; t < sends; t += Config::BLOCK_SIZE) {
                const int       other = (p.rank + 1 + t / PACKETS) % p.world;
                const int       i     = t % PACKETS;
                const uint32x4 *src =
                    static_cast<const uint32x4 *>(p.recv[p.rank]) + ar_slot(call, other, block, i);
                uint32x4 packet;
                do {
                    packet = load_nt(src);
                } while (packet.w != call);
                uint32_t *rows = reinterpret_cast<uint32_t *>(s.rows[other]) + 3 * i;
                rows[0]        = packet.x;
                rows[1]        = packet.y;
                rows[2]        = packet.z;
            }
            block_sync_lds();
            if (tid == 0) {
                p.calls[block] = call;
            }
        }
    } else {
        // all-reduce: block k swaps its rows with block k of every other rank, a packet 8 outputs in one
        // 16 B store, which lands whole. No tag: a slot holds 0 until its packet lands and its receiver
        // zeroes it again after reading, and a packet's first output never has the bits of +0 (sent as
        // -0, which adds the same: the sum starts at +0). Two buffers by call parity: no rank gets two
        // calls ahead, and a slot is written again (two calls on) only after its zeroing, which ends with
        // the call that reads it. Slots DENSE_SLOT0 on: past the ones M <= 4 uses (its packets are never
        // zeroed). Every packet goes out before any is awaited.
        if (p.world > 1) {
            constexpr int PACKETS     = OUTPUTS / 8;
            constexpr int DENSE_SLOT0 = Config::AR_PACKETS - Config::AR_ROWS * Config::MAX_NUM_TOKENS / 8;
            static_assert(PACKETS * 8 == OUTPUTS && DENSE_SLOT0 >= Config::AR_ROWS * 4 / 6 &&
                          DENSE_SLOT0 + PACKETS <= Config::AR_PACKETS);
            const int sends = (p.world - 1) * PACKETS;
            for (int t = tid; t < sends; t += Config::BLOCK_SIZE) {
                const int other = (p.rank + 1 + t / PACKETS) % p.world;
                const int i     = t % PACKETS;
                uint32x4  mine  = reinterpret_cast<const uint32x4 *>(s.rows[p.rank])[i];
                mine.x |= (mine.x & 0xffffu) == 0 ? 0x8000u : 0u;
                store_peer(static_cast<uint32x4 *>(p.recv[other]) + ar_slot(call, p.rank, block, DENSE_SLOT0 + i), mine);
            }
            for (int t = tid; t < sends; t += Config::BLOCK_SIZE) {
                const int other = (p.rank + 1 + t / PACKETS) % p.world;
                const int i     = t % PACKETS;
                const uint32x4 *src =
                    static_cast<const uint32x4 *>(p.recv[p.rank]) + ar_slot(call, other, block, DENSE_SLOT0 + i);
                uint32x4  packet;
                do {
                    packet = load_nt(src);
                } while (packet.x == 0);
                reinterpret_cast<uint32x4 *>(s.rows[other])[i] = packet;
            }
            // zeroed once all of this thread's packets are in: a zeroing store ahead of a poll would hold
            // it back (a wave's memory accesses complete in order)
            for (int t = tid; t < sends; t += Config::BLOCK_SIZE) {
                const int other = (p.rank + 1 + t / PACKETS) % p.world;
                store_nt(static_cast<uint32x4 *>(p.recv[p.rank]) + ar_slot(call, other, block, DENSE_SLOT0 + t % PACKETS),
                         uint32x4{0, 0, 0, 0});
            }
            block_sync_lds();
            if (tid == 0) {
                p.calls[block] = call;
            }
        }
    }
    // in rank order, so every rank gets the same bits
#pragma unroll
    for (int k = 0; k < AR_ITEMS<NUM_TOKENS>; ++k) {
        const int t = tid + k * Config::BLOCK_SIZE;
        if (t < OUTPUTS) {
            float sum = 0.0f;
            for (int r = 0; r < p.world; ++r) {
                sum += static_cast<float>(s.rows[r][t]);
            }
            const bfloat16 val =
                p.accumulate
                    ? static_cast<bfloat16>(static_cast<float>(static_cast<bfloat16>(sum)) + prior[k])
                    : static_cast<bfloat16>(sum);
            bfloat16 *at = p.out + t / ROWS * Config::HIDDEN_SIZE + ROWS * block + t % ROWS;
            if constexpr (SC1) {
                store_sc1(at, val);
            } else {
                *at = val;
            }
        }
    }
}

} // namespace infera_flash::glm5_m16

// GLM-5.3 on 8 GPUs (TP8): the sizes every GLM-5 kernel is written for, per card where noted.
#pragma once

#include "common/hw.h"

namespace infera_flash::glm5_m16 {

struct Config : Hw {
    static constexpr int   HIDDEN_SIZE           = 6144;
    static constexpr int   QUANT_GROUP_SIZE      = 128; // one fp8 scale per 1x128 of activations
    static constexpr int   NUM_GROUPS            = HIDDEN_SIZE / QUANT_GROUP_SIZE;
    static constexpr int   NUM_EXPERTS           = 256;
    static constexpr int   INTERMEDIATE_SIZE     = 256; // per card: 2048 / TP8
    static constexpr int   TOP_K                 = 8;
    static constexpr float ROUTED_SCALING_FACTOR = 2.5f;
    static constexpr int   MAX_NUM_TOKENS        = 16; // rows a decode call takes: 4 MTP k=3 verifies
    // attention per card: q_a_proj's rows, kv_a_proj_with_mqa's (the kv latent, then the rope
    // part of k), qkv_a's (both), q_b_proj's; o_proj's K
    static constexpr int   Q_LORA_RANK           = 2048;
    static constexpr int   KV_LORA_RANK          = 512;
    static constexpr int   QK_ROPE_DIM           = 64;
    static constexpr int   QK_NOPE_DIM           = 192;
    static constexpr int   MLA_HEADS             = 8; // per card
    static constexpr int   V_HEAD_DIM            = 256;
    static constexpr int   QKV_A_ROWS            = Q_LORA_RANK + KV_LORA_RANK + QK_ROPE_DIM;
    static constexpr int   Q_B_ROWS              = MLA_HEADS * (QK_NOPE_DIM + QK_ROPE_DIM);
    static constexpr int   O_PROJ_K              = MLA_HEADS * V_HEAD_DIM;
    // the dense layers' MLP per card: gate_proj's rows, up_proj's (12288 / TP8)
    static constexpr int   DENSE_ROWS            = 1536;
    // the MTP layer's eh_proj rows per card (6144 / TP8)
    static constexpr int   MTP_ROWS              = HIDDEN_SIZE / 8;
    // the DSA indexer (replicated): heads, head dim, tokens per ki page
    static constexpr int   INDEX_HEADS           = 32;
    static constexpr int   INDEX_DIM             = 128;
    static constexpr int   INDEX_PAGE            = 64;
    static constexpr int   INDEX_TOPK            = 2048;
    // ExpertTable slots: the shared expert, then the most distinct experts M tokens can pick
    static constexpr int   MAX_SLOTS             = MAX_NUM_TOKENS * TOP_K + 1;
    // the shared expert's id: its weights come after the routed ones
    static constexpr int   SHARED_EXPERT         = NUM_EXPERTS;
    // the all-reduce (AllReduceParams): block k sums output rows AR_ROWS k .., a 16 B packet
    // carrying 6 of its AR_ROWS x M; receive buffer [call parity][source rank][block][packet]
    static constexpr int MAX_RANKS      = 8;
    static constexpr int AR_ROWS        = HIDDEN_SIZE / NUM_BLOCKS;
    static constexpr int AR_PACKETS     = AR_ROWS * MAX_NUM_TOKENS / 6;
    static constexpr int AR_BUFFER_SIZE = 2 * MAX_RANKS * NUM_BLOCKS * AR_PACKETS * 16;
};

// each thread's 16 B chunks of a HIDDEN_SIZE row, a block's threads covering it
constexpr int ROW_LOADS = Config::HIDDEN_SIZE / (Config::BLOCK_SIZE * 8);
static_assert(ROW_LOADS * Config::BLOCK_SIZE * 8 == Config::HIDDEN_SIZE);

} // namespace infera_flash::glm5_m16

// The MoE layer in one kernel (moe_block), one block per CU, for 1 to 16 tokens a call (glm5's 4):
// Infera-Flash's glm5/moe.h on glm5_m16's sizes (MAX_NUM_TOKENS 16), MXFP4 experts on the stream
// itself (no residual to add), without debug outputs. What glm5 lays out for 4 tokens and no longer
// fits is laid out anew: the router logits go out in packets of their own beside the sync slots,
// each wave picks the experts of every fourth token, gate_up's epilogue takes its items in turns,
// and h goes out and comes back only for the (slot, token) pairs a token picked, 9 a token, staged
// in down whole (h of every slot and token would not fit in LDS from 6 tokens on).
#pragma once

#include <type_traits>

#include "common/gemm.h"
#include "common/math.h"
#include "common/sync.h"
#include "glm5_m16/all_reduce.h"
#include "glm5_m16/config.h"
#include "aklr/norm.h"
#include "aklr/router.h"

namespace infera_flash::glm5_m16 {

// tokens are the 16 columns of every MFMA tile
static_assert(Config::MAX_NUM_TOKENS <= 16);

// slots of the tables below, whole rounds of down's experts past the last
constexpr int SLOTS_PADDED = (Config::MAX_SLOTS + 15) / 16 * 16;

// The experts to run: the shared one first, then the picked routed ones in id order, with each
// token's weight (1 for the shared expert, 0 where a token didn't pick a routed one), a token's
// row of slots in one piece for down to read a round of them at once.
struct ExpertTable {
    float w[Config::MAX_NUM_TOKENS][SLOTS_PADDED];
    int   ids[SLOTS_PADDED];
    int   count;
};

// The (slot, token) pairs whose weight is nonzero, 9 a token: pair 1 + t is token t's shared
// expert, 1 + M + 8 m + k token m's pick k. gate_up writes h of these alone and down reads them
// back; pair 0 stands for every other (slot, token), its h taken as 0. In LDS as the table's w,
// [MAX_NUM_TOKENS][SLOTS_PADDED].
constexpr int MAX_PAIRS = 1 + Config::MAX_NUM_TOKENS * (Config::TOP_K + 1);
static_assert(MAX_PAIRS <= 256); // a pair's number in a byte

// down of every expert in the table times its routing weight, summed in table order, then over the
// TP ranks.
struct DownParams {
    const bfloat16 *h; // MoeParams::act
    // [NUM_EXPERTS + 1, HIDDEN_SIZE, INTERMEDIATE_SIZE] in gate_up's format, preshuffled like its
    // weights, with scales [NUM_EXPERTS + 1, HIDDEN_SIZE, INTERMEDIATE_SIZE / 32] shuffled like its
    // scales
    const uint8_t  *weight;
    const void     *weight_scale;
    AllReduceParams ar;
};

// sync (1)'s packets of one block, {3 logits, epoch} each: its expert's logit of every token
constexpr int LOGIT_PACKETS = (Config::MAX_NUM_TOKENS + 2) / 3;
// bytes of them for every block, [NUM_BLOCKS][LOGIT_PACKETS]; zero them once at allocation, as the
// sync workspace
constexpr int LOGITS_SIZE = Config::NUM_BLOCKS * LOGIT_PACKETS * sizeof(uint32x4);

// Shapes use M = num_tokens. The whole MoE layer in one kernel: RMSNorm, router, x quant, sync (1),
// top-k, grouping, gate_up, sync (2) on its h, then down and the all-reduce.
struct MoeParams {
    const bfloat16 *h;             // [M, HIDDEN_SIZE] the stream
    const bfloat16 *gamma;         // [HIDDEN_SIZE] post-attention RMSNorm weight
    const bfloat16 *router_weight; // [NUM_EXPERTS, HIDDEN_SIZE]
    const float    *router_bias;   // [NUM_EXPERTS]
    void           *workspace;     // WORKSPACE_SIZE bytes
    uint32x4       *logits;        // LOGITS_SIZE bytes
    float           epsilon;
    float           routed_scaling_factor;
    // [NUM_EXPERTS + 1, 2 * INTERMEDIATE_SIZE, HIDDEN_SIZE], gate rows then up rows, preshuffled by
    // aiter shuffle_weight(w, (16, 16)): e2m1 pairs, the lower K in the low nibble, with e8m0 scales
    // [NUM_EXPERTS + 1, 2 * INTERMEDIATE_SIZE, HIDDEN_SIZE / 32] in aiter shuffle_scale's layout
    // (e8m0_dword); x and h are then quantized as aiter does (quant_mxfp4)
    const uint8_t *gate_up_weight;
    const void    *gate_up_scale;
    // gate_up's h = silu(x gate^T) * (x up^T), rounded as HF does, of the nonzero pairs:
    // [MAX_PAIRS, INTERMEDIATE_SIZE], row 0 unused
    bfloat16  *act;
    DownParams down; // its h is act
};

// LDS layout, byte offsets into the dynamic smem. What the whole kernel keeps comes first, zeroed
// each call before the top-k: the table, each (slot, token)'s pair (0 for none) and a bit per
// expert picked by any token
constexpr int SMEM_TABLE_OFFSET = 0;
constexpr int SMEM_PAIRS_OFFSET = SMEM_TABLE_OFFSET + (sizeof(ExpertTable) + 15) / 16 * 16;
constexpr int SMEM_PICKED_MASK_OFFSET =
    SMEM_PAIRS_OFFSET + Config::MAX_NUM_TOKENS * SLOTS_PADDED;
constexpr int SMEM_ZEROED_SIZE = SMEM_PICKED_MASK_OFFSET + Config::NUM_EXPERTS / 8;
// the block reduce's scratch [WAVES][M]
constexpr int SMEM_REDUCE_OFFSET = SMEM_ZEROED_SIZE;
// x MXFP4 [MAX_NUM_TOKENS][HIDDEN_SIZE / 2], row-major, then its e8m0 [MAX_NUM_TOKENS][HIDDEN_SIZE /
// 32]
constexpr int SMEM_X_OFFSET =
    SMEM_REDUCE_OFFSET + WAVES * Config::MAX_NUM_TOKENS * sizeof(float);
constexpr int SMEM_X_SCALE_OFFSET =
    SMEM_X_OFFSET + Config::MAX_NUM_TOKENS * Config::HIDDEN_SIZE / 2;
// router logits fp32 [MAX_NUM_TOKENS][NUM_EXPERTS], gathered from all blocks
constexpr int SMEM_LOGITS_OFFSET =
    SMEM_X_SCALE_OFFSET + Config::MAX_NUM_TOKENS * Config::HIDDEN_SIZE / 32;
// top-k expert ids int32 and weights fp32, each [MAX_NUM_TOKENS][TOP_K]
constexpr int SMEM_TOPK_IDS_OFFSET =
    SMEM_LOGITS_OFFSET + Config::MAX_NUM_TOKENS * Config::NUM_EXPERTS * sizeof(float);
constexpr int SMEM_TOPK_W_OFFSET =
    SMEM_TOPK_IDS_OFFSET + Config::MAX_NUM_TOKENS * Config::TOP_K * sizeof(int);
constexpr int SMEM_TOPK_END =
    SMEM_TOPK_W_OFFSET + Config::MAX_NUM_TOKENS * Config::TOP_K * sizeof(float);
static_assert(SMEM_ZEROED_SIZE % 16 == 0 && SMEM_X_OFFSET % 16 == 0 && SMEM_TOPK_END % 16 == 0);

// a block's sync slot: sync (2)'s {epoch} in packet 0, the one next_epoch reads
constexpr int SYNC2_PACKET = 0;

__device__ inline float sigmoid(float x) {
    return __builtin_amdgcn_rcpf(1.0f + __expf(-x));
}

// WarpReduce (common/device.h) of N values side by side: each step for all of them before the
// next, so their chains of dependent DPP steps overlap instead of running one after another. A
// value's own steps, and so its bits, are WarpReduce's.
template <template <class> class Func, int WIDTH = THREADS_PER_WARP, typename T, int N>
__device__ __forceinline__ void warp_reduce_n(T (&vals)[N]) {
    static_assert(WIDTH == 4 || WIDTH == THREADS_PER_WARP);
#pragma unroll
    for (int n = 0; n < N; ++n) {
        vals[n] = Func<T>::op(dpp_mov<0xB1>(vals[n]), vals[n]); // quad_perm [1,0,3,2]
    }
#pragma unroll
    for (int n = 0; n < N; ++n) {
        vals[n] = Func<T>::op(dpp_mov<0x4E>(vals[n]), vals[n]); // quad_perm [2,3,0,1]
    }
    if constexpr (WIDTH == THREADS_PER_WARP) {
#pragma unroll
        for (int n = 0; n < N; ++n) {
            vals[n] = Func<T>::op(dpp_mov<0x141>(vals[n]), vals[n]); // row_half_mirror
        }
#pragma unroll
        for (int n = 0; n < N; ++n) {
            vals[n] = Func<T>::op(dpp_mov<0x140>(vals[n]), vals[n]); // row_mirror
        }
#pragma unroll
        for (int n = 0; n < N; ++n) {
            vals[n] = Func<T>::op(vals[n], dpp_mov<0x142>(vals[n])); // row_bcast:15
        }
#pragma unroll
        for (int n = 0; n < N; ++n) {
            vals[n] = Func<T>::op(vals[n], dpp_mov<0x143>(vals[n])); // row_bcast:31
        }
#pragma unroll
        for (int n = 0; n < N; ++n) {
            vals[n] = readlane(vals[n], 63);
        }
    }
}

// BlockReduce (common/device.h) on warp_reduce_n: the same bits
template <template <class> class Func, bool LDS_ONLY = false, typename T, int N>
__device__ __forceinline__ void block_reduce_n(T (&vals)[N], T *smem) {
    const auto sync = [] {
        if constexpr (LDS_ONLY) {
            block_sync_lds();
        } else {
            __syncthreads();
        }
    };
    const int warp_id = threadIdx.x / THREADS_PER_WARP;
    warp_reduce_n<Func>(vals);
    if (threadIdx.x % THREADS_PER_WARP == 0) {
#pragma unroll
        for (int n = 0; n < N; ++n) {
            smem[warp_id * N + n] = vals[n];
        }
    }
    sync();
#pragma unroll
    for (int n = 0; n < N; ++n) {
        vals[n] = smem[n];
#pragma unroll
        for (int w = 1; w < WAVES; ++w) {
            vals[n] = Func<T>::op(vals[n], smem[w * N + n]);
        }
    }
    sync();
}

// block_reduce_n with its first sync alone: the caller reuses no part of smem afterwards
template <template <class> class Func, typename T, int N>
__device__ __forceinline__ void block_reduce_n_once(T (&vals)[N], T *smem) {
    const int warp_id = threadIdx.x / THREADS_PER_WARP;
    warp_reduce_n<Func>(vals);
    if (threadIdx.x % THREADS_PER_WARP == 0) {
#pragma unroll
        for (int n = 0; n < N; ++n) {
            smem[warp_id * N + n] = vals[n];
        }
    }
    block_sync_lds();
#pragma unroll
    for (int n = 0; n < N; ++n) {
        vals[n] = smem[n];
#pragma unroll
        for (int w = 1; w < WAVES; ++w) {
            vals[n] = Func<T>::op(vals[n], smem[w * N + n]);
        }
    }
}

// quant_mxfp4 (common/math.h) of a group whose amax, as bf16 bits A (sign cleared), lies in
// [384, 0x7F80): its e8m0 is then (A - 193) >> 7, what amax / 6 rounded up to a power of two comes
// to for a bf16 amax, and the bf16 pairs convert as they are. range keeps the max of A - 384
// (unsigned): from QUANT_RANGE_END on, a group was out of the range (0, tiny, inf or NaN amax) and
// its results are void, for the caller to quantize again with quant_mxfp4.
constexpr uint32_t QUANT_RANGE_END = 0x7F80 - 384;
__device__ inline int quant_mxfp4_fast(const bfloat16 (&x)[8], uint8_t *q, uint32_t &range) {
    using ushort2  = uint16_t __attribute__((ext_vector_type(2)));
    const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x);
    ushort2     mag[4];
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        mag[j] = __builtin_bit_cast(ushort2, __builtin_bit_cast(uint32_t, x2[j]) & 0x7fff7fffu);
    }
    const ushort2  top  = __builtin_elementwise_max(__builtin_elementwise_max(mag[0], mag[1]),
                                                    __builtin_elementwise_max(mag[2], mag[3]));
    const uint32_t amax = WarpReduce<MaxOp, uint32_t, 4>(
        top.x > top.y ? static_cast<uint32_t>(top.x) : static_cast<uint32_t>(top.y));
    range                = range > amax - 384u ? range : amax - 384u;
    const uint32_t e8m0  = (amax - 193u) >> 7;
    const float    scale = __uint_as_float(e8m0 << 23);
    uint32_t       codes = __builtin_amdgcn_cvt_scalef32_pk_fp4_bf16(0, x2[0], scale, 0);
    codes                = __builtin_amdgcn_cvt_scalef32_pk_fp4_bf16(codes, x2[1], scale, 1);
    codes                = __builtin_amdgcn_cvt_scalef32_pk_fp4_bf16(codes, x2[2], scale, 2);
    codes                = __builtin_amdgcn_cvt_scalef32_pk_fp4_bf16(codes, x2[3], scale, 3);
    *reinterpret_cast<uint32_t *>(q) = codes;
    return static_cast<int>(e8m0);
}
// quant_mxfp4_fast of B groups side by side, each step for all of them before the next; a group's
// own steps, and so its bits, are quant_mxfp4_fast's
template <int B>
__device__ __forceinline__ void quant_mxfp4_fast_n(const bfloat16 (&x)[B][8], uint8_t *const (&q)[B],
                                                   int (&e8m0)[B], uint32_t &range) {
    using ushort2 = uint16_t __attribute__((ext_vector_type(2)));
    uint32_t amax[B];
#pragma unroll
    for (int b = 0; b < B; ++b) {
        const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x[b]);
        ushort2     mag[4];
#pragma unroll
        for (int j = 0; j < 4; ++j) {
            mag[j] = __builtin_bit_cast(ushort2, __builtin_bit_cast(uint32_t, x2[j]) & 0x7fff7fffu);
        }
        const ushort2 top = __builtin_elementwise_max(__builtin_elementwise_max(mag[0], mag[1]),
                                                      __builtin_elementwise_max(mag[2], mag[3]));
        amax[b] = top.x > top.y ? static_cast<uint32_t>(top.x) : static_cast<uint32_t>(top.y);
    }
    warp_reduce_n<MaxOp, 4>(amax);
    float scale[B];
#pragma unroll
    for (int b = 0; b < B; ++b) {
        range                = range > amax[b] - 384u ? range : amax[b] - 384u;
        const uint32_t e     = (amax[b] - 193u) >> 7;
        e8m0[b]              = static_cast<int>(e);
        scale[b]             = __uint_as_float(e << 23);
    }
    uint32_t codes[B];
#pragma unroll
    for (int b = 0; b < B; ++b) {
        const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x[b]);
        // amax[b] as the old value: the four conversions write all of codes' bytes
        codes[b]       = __builtin_amdgcn_cvt_scalef32_pk_fp4_bf16(amax[b], x2[0], scale[b], 0);
    }
#pragma unroll
    for (int b = 0; b < B; ++b) {
        const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x[b]);
        codes[b]       = __builtin_amdgcn_cvt_scalef32_pk_fp4_bf16(codes[b], x2[1], scale[b], 1);
    }
#pragma unroll
    for (int b = 0; b < B; ++b) {
        const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x[b]);
        codes[b]       = __builtin_amdgcn_cvt_scalef32_pk_fp4_bf16(codes[b], x2[2], scale[b], 2);
    }
#pragma unroll
    for (int b = 0; b < B; ++b) {
        const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x[b]);
        codes[b]       = __builtin_amdgcn_cvt_scalef32_pk_fp4_bf16(codes[b], x2[3], scale[b], 3);
    }
#pragma unroll
    for (int b = 0; b < B; ++b) {
        *reinterpret_cast<uint32_t *>(q[b]) = codes[b];
    }
}
// whether any lane's groups went out of quant_mxfp4_fast's range
__device__ inline bool quant_range_out(uint32_t range) {
    return __ballot(range >= QUANT_RANGE_END) != 0;
}

// Loads N consecutive 16 B packets with sc1, waiting once for all of them: common/device.h's
// load_sc1 for up to LOGIT_PACKETS. One asm statement: nothing may read a packet before the wait.
template <int N> __device__ inline void load_packets_sc1(const uint32x4 *ptr, uint32x4 (&v)[N]) {
    static_assert(N >= 1 && N <= 6);
    if constexpr (N <= 2) {
        load_sc1(ptr, v);
    } else if constexpr (N == 3) {
        asm volatile("global_load_dwordx4 %0, %3, off sc1\n\t"
                     "global_load_dwordx4 %1, %3, off offset:16 sc1\n\t"
                     "global_load_dwordx4 %2, %3, off offset:32 sc1\n\t"
                     "s_waitcnt vmcnt(0)"
                     : "=&v"(v[0]), "=&v"(v[1]), "=&v"(v[2])
                     : "v"(ptr)
                     : "memory");
    } else if constexpr (N == 4) {
        asm volatile("global_load_dwordx4 %0, %4, off sc1\n\t"
                     "global_load_dwordx4 %1, %4, off offset:16 sc1\n\t"
                     "global_load_dwordx4 %2, %4, off offset:32 sc1\n\t"
                     "global_load_dwordx4 %3, %4, off offset:48 sc1\n\t"
                     "s_waitcnt vmcnt(0)"
                     : "=&v"(v[0]), "=&v"(v[1]), "=&v"(v[2]), "=&v"(v[3])
                     : "v"(ptr)
                     : "memory");
    } else if constexpr (N == 5) {
        asm volatile("global_load_dwordx4 %0, %5, off sc1\n\t"
                     "global_load_dwordx4 %1, %5, off offset:16 sc1\n\t"
                     "global_load_dwordx4 %2, %5, off offset:32 sc1\n\t"
                     "global_load_dwordx4 %3, %5, off offset:48 sc1\n\t"
                     "global_load_dwordx4 %4, %5, off offset:64 sc1\n\t"
                     "s_waitcnt vmcnt(0)"
                     : "=&v"(v[0]), "=&v"(v[1]), "=&v"(v[2]), "=&v"(v[3]), "=&v"(v[4])
                     : "v"(ptr)
                     : "memory");
    } else {
        asm volatile("global_load_dwordx4 %0, %6, off sc1\n\t"
                     "global_load_dwordx4 %1, %6, off offset:16 sc1\n\t"
                     "global_load_dwordx4 %2, %6, off offset:32 sc1\n\t"
                     "global_load_dwordx4 %3, %6, off offset:48 sc1\n\t"
                     "global_load_dwordx4 %4, %6, off offset:64 sc1\n\t"
                     "global_load_dwordx4 %5, %6, off offset:80 sc1\n\t"
                     "s_waitcnt vmcnt(0)"
                     : "=&v"(v[0]), "=&v"(v[1]), "=&v"(v[2]), "=&v"(v[3]), "=&v"(v[4]),
                       "=&v"(v[5])
                     : "v"(ptr)
                     : "memory");
    }
}

// gate_up: an item is 8 gate rows and the matching 8 up rows of one expert, one 16-row MFMA tile,
// chunk c of its 32 taking intermediate columns 8c .. 8c + 7. Block b's item n is slot b % 8 + 8n,
// so an XCD's blocks take whole experts, and chunk (b / 8 + n) % 32, so a block's chunks alternate
// between the two halves of a 16-row group; the 4 waves split K, 12 blocks of 128 each.
constexpr int WAVE_K_BLOCKS    = Config::NUM_GROUPS / WAVES;
constexpr int ITEMS_PER_EXPERT = Config::INTERMEDIATE_SIZE / 8;
// a block's items at most, M tokens' table
template <int NUM_TOKENS>
constexpr int MAX_ITEMS_OF =
    ((NUM_TOKENS * Config::TOP_K + 1) * ITEMS_PER_EXPERT + Config::NUM_BLOCKS - 1) /
    Config::NUM_BLOCKS;
constexpr int MAX_ITEMS = MAX_ITEMS_OF<Config::MAX_NUM_TOKENS>;
// a 16-row group of preshuffled MXFP4 weights
constexpr int GROUP_BYTES = 16 * Config::HIDDEN_SIZE / 2;
// LDS: each wave's 16x16 fp32 result per item [MAX_ITEMS][4][64 lanes][4]
constexpr int SMEM_GATE_UP_SIZE = MAX_ITEMS * Config::BLOCK_SIZE * sizeof(floatx4);

// Runs run(std::integral_constant<int, n>{}) for n = num_items in 1 .. N: straight-line code per item
// count, so the compiler can count the loads in flight exactly.
template <int N, typename Run>
__device__ __forceinline__ void run_items(int num_items, const Run &run) {
    if (num_items == N) {
        run(std::integral_constant<int, N>{});
    } else if constexpr (N > 1) {
        run_items<N - 1>(num_items, run);
    }
}

// gate_up's first item's weights, issued before the grouping (EARLY0)
struct GateUpFirst {
    int32x4 w[WAVE_K_BLOCKS];
    int     w_e8m0[WAVE_K_BLOCKS / 2];
};
// gate_up_block without a hook
struct NoHook {
    __device__ void operator()() const {}
};
// M whose gate_up epilogue takes four threads per (item, token), two rows each (their h stores then
// reach waves 2 and 3 too: every wave waits for its stores before the publish)
template <int NUM_TOKENS> constexpr bool EPILOGUE4 = NUM_TOKENS == 4 || NUM_TOKENS == 8;
// gate_up's partial sums of M tokens' items
template <int NUM_TOKENS>
constexpr int SMEM_GATE_UP_SIZE_OF = MAX_ITEMS_OF<NUM_TOKENS> * Config::BLOCK_SIZE * static_cast<int>(sizeof(floatx4));

// This block's gate_up items, x, its scales, the table and the pairs in LDS; smem takes the partial
// sums. h of the nonzero pairs goes out in 16 B sc1 stores, for blocks on other XCDs to read.
// EARLY0: the first item's weights come in first; between() (a hook) runs before the last item's
// MFMAs, behind its loads.
template <int NUM_TOKENS, bool EARLY0 = false, typename Between = NoHook>
__device__ __forceinline__ void gate_up_block(const uint8_t *x_q, const uint8_t *x_s,
                                              const ExpertTable &table, const uint8_t *pairs,
                                              const uint8_t *weight, const void *weight_scale,
                                              bfloat16 *h, uint8_t *smem,
                                              const GateUpFirst *first = nullptr,
                                              const Between &between = {}) {
    constexpr int ITEMS = MAX_ITEMS_OF<NUM_TOKENS>;
    static_assert(WAVE_K_BLOCKS % 2 == 0); // two K blocks per e8m0 dword
    floatx4  *partials  = reinterpret_cast<floatx4 *>(smem);
    const int tid       = threadIdx.x;
    const int lane      = tid % THREADS_PER_WARP;
    const int kb0       = tid / THREADS_PER_WARP * WAVE_K_BLOCKS;
    static_assert(Config::NUM_BLOCKS == 8 * ITEMS_PER_EXPERT);
    const int xcd       = blockIdx.x % 8;
    const int count     = __builtin_amdgcn_readfirstlane(table.count);
    const int num_items = (count - xcd + 7) / 8;
    if (num_items <= 0) {
        return;
    }
    const auto slot_of  = [&](int n) { return min(xcd + 8 * n, Config::MAX_SLOTS - 1); };
    const auto chunk_of = [&](int n) { return (blockIdx.x / 8 + n) % ITEMS_PER_EXPERT; };

    // everything but the weights first: global loads complete in issue order, so waiting for one
    // issued after the weights would wait for all of them. Past count, ids are 0.
    int experts[ITEMS];
#pragma unroll
    for (int n = 0; n < ITEMS; ++n) {
        experts[n] = __builtin_amdgcn_readfirstlane(table.ids[slot_of(n)]);
    }
    // x is every item's B operand, with its scales (lane l's e8m0, of K 32 (l / 16) on); columns
    // past M repeat token M - 1 and are dropped
    const int token = min(lane % 16, NUM_TOKENS - 1);
    int32x4   x[WAVE_K_BLOCKS];
    int       x_scale[WAVE_K_BLOCKS];
#pragma unroll
    for (int j = 0; j < WAVE_K_BLOCKS; ++j) {
        x[j] = *reinterpret_cast<const int32x4 *>(x_q + token * Config::HIDDEN_SIZE / 2 +
                                                  (kb0 + j) * 64 + lane / 16 * 16);
        x_scale[j] = x_s[token * Config::HIDDEN_SIZE / 32 + (kb0 + j) * 4 + lane / 16];
    }

    // lanes l % 16 < 8 take gate rows, the others the matching up rows; their results land in C
    // rows 0-7 (lanes 0-31) and 8-15 (lanes 32-63)
    const auto row_of   = [&](int n) { return 8 * (chunk_of(n) % 2) + lane % 8; }; // of its group
    const auto group_of = [&](int n) {
        return experts[n] * 2 * Config::INTERMEDIATE_SIZE / 16 +
               (lane % 16 < 8 ? 0 : Config::INTERMEDIATE_SIZE / 16) + chunk_of(n) / 2;
    };
    const auto weight_of = [&](int n) {
        return weight + static_cast<size_t>(group_of(n)) * GROUP_BYTES +
               kb0 * K_BLOCK_BYTES_OF<true> + lane / 16 * 256 + row_of(n) * 16;
    };
    // lane l's e8m0 of K blocks kb0 + 2p and kb0 + 2p + 1 share a dword, at bytes 0 and 2 once
    // shifted right by shift_of(n) (the row's half of its 32-row block)
    const auto shift_of  = [&](int n) { return chunk_of(n) / 2 % 2 * 8; };
    const auto scales_of = [&](int n) {
        return static_cast<const uint8_t *>(weight_scale) +
               e8m0_dword<Config::HIDDEN_SIZE / 32>(group_of(n) * 16 + row_of(n),
                                                    4 * kb0 + lane / 16);
    };
    // w[j] holds this wave's K block j of item n, w_e8m0[j / 2] its scales; with prefetch, it loads
    // the next item's as soon as its MFMA has read it
    int32x4    w[WAVE_K_BLOCKS];
    int        w_e8m0[WAVE_K_BLOCKS / 2];
    const auto load_w = [&](int j, int n) {
        const uint8_t *item = weight_of(n);
        if (j % 2 == 0) {
            w_e8m0[j / 2] = *reinterpret_cast<const int *>(scales_of(n) + j / 2 * 256);
        }
        w[j] = __builtin_nontemporal_load(
            reinterpret_cast<const int32x4 *>(item + j * K_BLOCK_BYTES_OF<true>));
    };
    if constexpr (EARLY0) {
#pragma unroll
        for (int j = 0; j < WAVE_K_BLOCKS; ++j) {
            w[j] = first->w[j];
        }
#pragma unroll
        for (int j = 0; j < WAVE_K_BLOCKS / 2; ++j) {
            w_e8m0[j] = first->w_e8m0[j];
        }
    } else {
#pragma unroll
        for (int j = 0; j < WAVE_K_BLOCKS; ++j) {
            load_w(j, 0);
        }
    }

    // the scales go into the instruction, which accumulates
    const auto item = [&](int n, auto prefetch) {
        floatx4 acc = {};
#pragma unroll
        for (int p = 0; p < WAVE_K_BLOCKS / 2; ++p) {
            const int w_scale = w_e8m0[p] >> shift_of(n);
            acc = mfma_16x16x128_fp4<0, 0>(w[2 * p], x[2 * p], w_scale, x_scale[2 * p], acc);
            acc = mfma_16x16x128_fp4<2, 0>(w[2 * p + 1], x[2 * p + 1], w_scale,
                                           x_scale[2 * p + 1], acc);
            if constexpr (prefetch) {
                load_w(2 * p, n + 1);
                load_w(2 * p + 1, n + 1);
            }
        }
        partials[n * Config::BLOCK_SIZE + tid] = acc;
    };
    run_items<ITEMS>(num_items, [&](auto items) {
#pragma unroll
        for (int n = 0; n < items - 1; ++n) {
            item(n, std::true_type{});
        }
        between();
        item(items - 1, std::false_type{});
    });
    // with a hook, its loads stay in flight past the items
    if constexpr (std::is_same_v<Between, NoHook>) {
        __syncthreads();
    } else {
        block_sync_lds();
    }

    // EPILOGUE4: thread (n, m, q) takes rows 2 q, 2 q + 1 of the gate and the up rows of thread
    // (n, m) below (q of 4), a quarter of its chain (the same sums, so the same bits)
    if constexpr (EPILOGUE4<NUM_TOKENS>) {
        constexpr int SPLIT  = 4;
        constexpr int SPLIT_TURNS = (ITEMS * NUM_TOKENS * SPLIT + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE;
#pragma unroll
        for (int k = 0; k < SPLIT_TURNS; ++k) {
            const int t  = tid + k * Config::BLOCK_SIZE;
            const int q  = t % SPLIT;
            const int nm = t / SPLIT;
            const int n  = nm / NUM_TOKENS;
            const int m  = nm % NUM_TOKENS;
            if (nm < num_items * NUM_TOKENS) {
                const int pair = pairs[m * SLOTS_PADDED + slot_of(n)];
                if (pair != 0) {
                    // rows 2 q, 2 q + 1: elements 2 (q % 2) on of lane 16 (q / 2) + m's floatx4
                    const floatx2 *tile = reinterpret_cast<const floatx2 *>(
                                              partials + n * Config::BLOCK_SIZE + m + 16 * (q / 2)) +
                                          q % 2;
                    float gate[2] = {};
                    float up[2]   = {};
#pragma unroll
                    for (int v = 0; v < WAVES; ++v) {
                        const floatx2 g = tile[2 * v * THREADS_PER_WARP];
                        const floatx2 u = tile[2 * (v * THREADS_PER_WARP + 32)];
#pragma unroll
                        for (int e = 0; e < 2; ++e) {
                            gate[e] += g[e];
                            up[e] += u[e];
                        }
                    }
                    bfloat16 val[2];
#pragma unroll
                    for (int j = 0; j < 2; ++j) {
                        val[j] = silu_mul(static_cast<bfloat16>(gate[j]), static_cast<bfloat16>(up[j]));
                    }
                    store_sc1(reinterpret_cast<uint32_t *>(h + pair * Config::INTERMEDIATE_SIZE +
                                                           8 * chunk_of(n) + 2 * q),
                              __builtin_bit_cast(uint32_t, val));
                }
            }
        }
        return;
    }
    // thread (n, m), in turns: token m's 8 gate rows and 8 up rows of item n, each summed over the
    // 4 waves in a fixed order, when (its slot, m) is a pair; C row r of a wave's tile is at lane
    // 16 (r / 4) + m, element r % 4
    constexpr int TURNS = (ITEMS * NUM_TOKENS + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE;
#pragma unroll
    for (int k = 0; k < TURNS; ++k) {
        const int t = tid + k * Config::BLOCK_SIZE;
        const int n = t / NUM_TOKENS;
        const int m = t % NUM_TOKENS;
        if (t < num_items * NUM_TOKENS) {
            const int pair = pairs[m * SLOTS_PADDED + slot_of(n)];
            if (pair != 0) {
                const floatx4 *tile    = partials + n * Config::BLOCK_SIZE + m;
                float          gate[8] = {};
                float          up[8]   = {};
#pragma unroll
                for (int v = 0; v < WAVES; ++v) {
#pragma unroll
                    for (int q = 0; q < 2; ++q) {
                        const floatx4 g = tile[v * THREADS_PER_WARP + 16 * q];
                        const floatx4 u = tile[v * THREADS_PER_WARP + 32 + 16 * q];
#pragma unroll
                        for (int e = 0; e < 4; ++e) {
                            gate[4 * q + e] += g[e];
                            up[4 * q + e] += u[e];
                        }
                    }
                }
                // HF: g and u are bf16 outputs of the linears
                bfloat16 val[8];
#pragma unroll
                for (int j = 0; j < 8; ++j) {
                    val[j] = silu_mul(static_cast<bfloat16>(gate[j]), static_cast<bfloat16>(up[j]));
                }
                store_sc1(reinterpret_cast<uint32x4 *>(h + pair * Config::INTERMEDIATE_SIZE +
                                                       8 * chunk_of(n)),
                          __builtin_bit_cast(uint32x4, val));
            }
        }
    }
}

// EARLY0: gate_up_block's load_w(j, 0) of every K block of this wave, for this block's first item's
// expert (expert0), before the grouping writes the table
__device__ __forceinline__ void gate_up_issue0(const uint8_t *weight, const void *weight_scale,
                                               int expert0, GateUpFirst &f) {
    const int  tid   = threadIdx.x;
    const int  lane  = tid % THREADS_PER_WARP;
    const int  kb0   = tid / THREADS_PER_WARP * WAVE_K_BLOCKS;
    const int  chunk = (blockIdx.x / 8) % ITEMS_PER_EXPERT;
    const int  row   = 8 * (chunk % 2) + lane % 8;
    const int  group = expert0 * 2 * Config::INTERMEDIATE_SIZE / 16 +
                      (lane % 16 < 8 ? 0 : Config::INTERMEDIATE_SIZE / 16) + chunk / 2;
    const uint8_t *item = weight + static_cast<size_t>(group) * GROUP_BYTES +
                          kb0 * K_BLOCK_BYTES_OF<true> + lane / 16 * 256 + row * 16;
    const uint8_t *scales = static_cast<const uint8_t *>(weight_scale) +
                            e8m0_dword<Config::HIDDEN_SIZE / 32>(group * 16 + row, 4 * kb0 + lane / 16);
#pragma unroll
    for (int j = 0; j < WAVE_K_BLOCKS; ++j) {
        if (j % 2 == 0) {
            f.w_e8m0[j / 2] = *reinterpret_cast<const int *>(scales + j / 2 * 256);
        }
        f.w[j] = __builtin_nontemporal_load(
            reinterpret_cast<const int32x4 *>(item + j * K_BLOCK_BYTES_OF<true>));
    }
}

// down: every expert with the row split in all_reduce.h, wave w taking 128-K block w % 2 of its
// group, in table order a round of DOWN_ROUND at a time. While the other blocks finish gate_up,
// the first DOWN_STAGED experts' weights go straight into LDS (buffer loads to LDS take no
// registers); the experts past them stream through registers, each wave keeping the next
// DOWN_DEPTH experts' weights in flight, the first of them landing while it takes the staged ones.
constexpr int DOWN_ROUND       = 8;
constexpr int DOWN_DEPTH       = 16;
constexpr int DOWN_GROUP_BYTES = 16 * Config::INTERMEDIATE_SIZE / 2; // MXFP4
// an expert's down weights and their e8m0: the same offsets in every expert's from there on
constexpr int DOWN_EXPERT_BYTES       = Config::HIDDEN_SIZE * Config::INTERMEDIATE_SIZE / 2;
constexpr int DOWN_EXPERT_SCALE_BYTES = Config::HIDDEN_SIZE * Config::INTERMEDIATE_SIZE / 32;
static_assert(Config::HIDDEN_SIZE % 32 == 0 && SLOTS_PADDED % DOWN_ROUND == 0);
static_assert(DOWN_GROUP_BYTES == 2 * K_BLOCK_BYTES_OF<true>); // two K blocks a group
// a pair's h in LDS: its two 128-K blocks in MXFP4, then their e8m0 (4 each), padded so that the
// pairs of a quarter wave's tokens start on different banks
constexpr int H_ROW  = 2 * 64 + 16;
constexpr int H_E8M0 = 2 * 64;
template <int NUM_TOKENS>
constexpr int H_BYTES = (1 + NUM_TOKENS * (Config::TOP_K + 1)) * H_ROW;

// down's LDS, over x and on: every wave is past gate_up once sync (2)'s publish returns
constexpr int SMEM_DOWN_OFFSET = SMEM_X_OFFSET;
// a staged expert's bytes (DownSmem): three K blocks of a 16-row group and two lanes' e8m0 dwords
constexpr int STAGED_BYTES = 3 * K_BLOCK_BYTES_OF<true> + 2 * THREADS_PER_WARP * sizeof(uint32_t);
template <int NUM_TOKENS>
constexpr int STAGED_FIT = (Config::SMEM_SIZE - SMEM_DOWN_OFFSET - H_BYTES<NUM_TOKENS> -
                            static_cast<int>(sizeof(RowsSmem))) /
                           STAGED_BYTES / DOWN_ROUND * DOWN_ROUND;
template <int NUM_TOKENS>
constexpr int DOWN_STAGED = STAGED_FIT<NUM_TOKENS> < 32 ? STAGED_FIT<NUM_TOKENS> : 32;

// A staged expert's weights of this block as the fp4 MFMA's lanes read them: w[0][r] and w[1][r]
// its full group's K blocks 0 and 1 (lane l's 16 B at 16 l), w[2][r] the half group's 8 rows of
// both (K block, quarter, row: 512 B each), s[r][0] and s[r][1] the full and the half group's e8m0
// dwords in lane order.
template <int NUM_TOKENS> struct DownSmem {
    uint8_t  h[H_BYTES<NUM_TOKENS>]; // pair 0 zeros
    RowsSmem rows;
    uint8_t  w[3][DOWN_STAGED<NUM_TOKENS>][K_BLOCK_BYTES_OF<true>];
    uint32_t s[DOWN_STAGED<NUM_TOKENS>][2][THREADS_PER_WARP];
};

// Lane l's 16 B (nt: the weights, read once) or 4 B (the e8m0) at offset + soffset into buffer, to
// LDS lds + 16 l or lds + 4 l. The builtin takes its size and cache policy as literals.
using LdsPtr = __attribute__((address_space(3))) void *;
__device__ __forceinline__ void load_to_lds_nt16(__amdgpu_buffer_rsrc_t buffer, int offset,
                                                 int soffset, void *lds) {
    __builtin_amdgcn_raw_ptr_buffer_load_lds(buffer, (LdsPtr)lds, 16, offset, soffset, 0, 2);
}
__device__ __forceinline__ void load_to_lds4(__amdgpu_buffer_rsrc_t buffer, int offset,
                                             int soffset, void *lds) {
    __builtin_amdgcn_raw_ptr_buffer_load_lds(buffer, (LdsPtr)lds, 4, offset, soffset, 0, 0);
}
__device__ __forceinline__ void load_to_lds16(__amdgpu_buffer_rsrc_t buffer, int offset,
                                              int soffset, void *lds) {
    __builtin_amdgcn_raw_ptr_buffer_load_lds(buffer, (LdsPtr)lds, 16, offset, soffset, 0, 0);
}

// all_reduce_residual's loads at the kernel's start, as the bf16 bits loaded (a thread past the 24
// M outputs loads the last one again): the compiler then waits for them where residual_of reads
// them. Unconditional (a buffer of 0 bytes without accumulate reads 0): behind a branch, the
// compiler converts them, and so waits for them, where they are loaded.
template <int NUM_TOKENS>
__device__ __forceinline__ void residual_bits(const AllReduceParams &p,
                                              uint16_t (&bits)[AR_ITEMS<NUM_TOKENS>]) {
    const auto prior =
        raw_buffer(p.prior, p.accumulate ? NUM_TOKENS * Config::HIDDEN_SIZE * sizeof(bfloat16) : 0);
#pragma unroll
    for (int k = 0; k < AR_ITEMS<NUM_TOKENS>; ++k) {
        const int t = min(static_cast<int>(threadIdx.x) + k * Config::BLOCK_SIZE,
                          Config::AR_ROWS * NUM_TOKENS - 1);
        bits[k]     = __builtin_amdgcn_raw_buffer_load_b16(
            prior,
            (t / Config::AR_ROWS * Config::HIDDEN_SIZE + Config::AR_ROWS * blockIdx.x +
             t % Config::AR_ROWS) * static_cast<int>(sizeof(bfloat16)),
            0, 0);
    }
}
// all_reduce_residual's values from residual_bits'
template <int NUM_TOKENS>
__device__ __forceinline__ void residual_of(const AllReduceParams &p,
                                            const uint16_t (&bits)[AR_ITEMS<NUM_TOKENS>],
                                            float (&prior)[AR_ITEMS<NUM_TOKENS>]) {
#pragma unroll
    for (int k = 0; k < AR_ITEMS<NUM_TOKENS>; ++k) {
        const int t = threadIdx.x + k * Config::BLOCK_SIZE;
        prior[k]    = p.accumulate && t < Config::AR_ROWS * NUM_TOKENS
                          ? __uint_as_float(static_cast<uint32_t>(bits[k]) << 16)
                          : 0.0f;
    }
}

// M whose all-reduce residual is loaded at the kernel's start (residual_bits): loaded past sync (2),
// the compiler converts it, and so waits for it, right there
template <int NUM_TOKENS> constexpr bool EARLY_RESIDUAL = NUM_TOKENS == 4 || NUM_TOKENS == 8;
// M whose first EARLY_SLOTS staged experts' DMA goes out before gate_up's last item, its staged
// experts laid out one after another (weights and e8m0 of one expert together, the first ones clear
// of gate_up's partial sums)
template <int NUM_TOKENS> constexpr bool EARLY_DMA = NUM_TOKENS == 4 || NUM_TOKENS == 8;
constexpr int EARLY_SLOTS = 4;
constexpr int SLOT_BYTES  = STAGED_BYTES;
// EARLY_DMA: staged experts 0 .. EARLY_SLOTS - 1 at the end of LDS (past gate_up's partial sums and
// clear of x, which gate_up may read again from LDS while the first of them land), the rest from s.w on
constexpr int SMEM_EARLY_SLOTS = Config::SMEM_SIZE - 256 - EARLY_SLOTS * SLOT_BYTES; // 256: probes' marks
template <int NUM_TOKENS> __device__ __forceinline__ uint8_t *slot_base(DownSmem<NUM_TOKENS> &s, int r) {
    if constexpr (EARLY_DMA<NUM_TOKENS>) {
        uint8_t *early = reinterpret_cast<uint8_t *>(&s) - SMEM_DOWN_OFFSET + SMEM_EARLY_SLOTS;
        uint8_t *rest  = reinterpret_cast<uint8_t *>(s.w) - EARLY_SLOTS * SLOT_BYTES;
        return (r < EARLY_SLOTS ? early : rest) + r * SLOT_BYTES;
    } else {
        return nullptr;
    }
}
template <int NUM_TOKENS> __device__ __forceinline__ uint8_t *staged_w(DownSmem<NUM_TOKENS> &s, int k, int r) {
    if constexpr (EARLY_DMA<NUM_TOKENS>) {
        return slot_base(s, r) + k * K_BLOCK_BYTES_OF<true>;
    } else {
        return s.w[k][r];
    }
}
template <int NUM_TOKENS> __device__ __forceinline__ uint32_t *staged_s(DownSmem<NUM_TOKENS> &s, int r, int g) {
    if constexpr (EARLY_DMA<NUM_TOKENS>) {
        return reinterpret_cast<uint32_t *>(slot_base(s, r) + 3 * K_BLOCK_BYTES_OF<true>) +
               g * THREADS_PER_WARP;
    } else {
        return s.s[r][g];
    }
}

// staged expert r's DMA (expert's id given) by this wave: the full group's two K blocks, the half
// group's 8 rows of both, both groups' e8m0
template <int NUM_TOKENS>
__device__ __forceinline__ void stage_expert(const DownParams &p, DownSmem<NUM_TOKENS> &s, int r, int expert) {
    const int  lane      = threadIdx.x % THREADS_PER_WARP;
    const auto weights   = raw_buffer(p.weight, (Config::NUM_EXPERTS + 1) * DOWN_EXPERT_BYTES);
    const auto scales    = raw_buffer(p.weight_scale, (Config::NUM_EXPERTS + 1) * DOWN_EXPERT_SCALE_BYTES);
    const int  full      = split_group(0);
    const int  half      = split_group(2);
    const int  half_row  = split_row(2, lane);
    const int  full_tile = full * DOWN_GROUP_BYTES + lane * 16;
    const int  half_tile = half * DOWN_GROUP_BYTES + lane / 32 * K_BLOCK_BYTES_OF<true> +
                          lane % 32 / 8 * 256 + half_row * 16;
    const int  full_e8m0 = e8m0_dword<Config::INTERMEDIATE_SIZE / 32>(full * 16 + lane % 16, lane / 16);
    const int  half_e8m0 = e8m0_dword<Config::INTERMEDIATE_SIZE / 32>(half * 16 + half_row, lane / 16);
    const int  w_at      = expert * DOWN_EXPERT_BYTES;
    const int  s_at      = expert * DOWN_EXPERT_SCALE_BYTES;
    load_to_lds_nt16(weights, full_tile, w_at, staged_w(s, 0, r));
    load_to_lds_nt16(weights, full_tile + K_BLOCK_BYTES_OF<true>, w_at, staged_w(s, 1, r));
    load_to_lds_nt16(weights, half_tile, w_at, staged_w(s, 2, r));
    load_to_lds4(scales, full_e8m0, s_at, staged_s(s, r, 0));
    load_to_lds4(scales, half_e8m0, s_at, staged_s(s, r, 1));
}

// The down of one block, table and pairs in LDS; call is the all-reduce's call number. publish()
// announces this block's h, the staged experts' weights go out, then wait() for every block's h
// (whose poll waits for those loads too).
template <int NUM_TOKENS, typename Publish, typename Wait>
__device__ __forceinline__ void down_block(const DownParams &p, const ExpertTable &table,
                                           const uint8_t *pairs, DownSmem<NUM_TOKENS> &s,
                                           uint32_t call, Publish publish, Wait wait,
                                           const uint16_t (&prior_bits)[AR_ITEMS<NUM_TOKENS>]) {
    constexpr int STAGED = DOWN_STAGED<NUM_TOKENS>;
    static_assert(STAGED > 0 && STAGED % DOWN_ROUND == 0 && STAGED <= THREADS_PER_WARP);
    static_assert(SMEM_DOWN_OFFSET + sizeof(DownSmem<NUM_TOKENS>) <= Config::SMEM_SIZE);
    const int tid   = threadIdx.x;
    const int lane  = tid % THREADS_PER_WARP;
    const int wave  = tid / THREADS_PER_WARP;
    const int group = split_group(wave);
    const int row   = split_row(wave, lane);
    const int kb    = wave % 2;

    const int count = __builtin_amdgcn_readfirstlane(table.count);

    // h of the nonzero pairs 1 .. 9 M, 16 lanes per 1x128 group: pair p's K block k is group
    // 2 p + k; past them, the last group again
    constexpr int H_GROUPS = NUM_TOKENS * (Config::TOP_K + 1) * 2;
    constexpr int H_ITERS  = (H_GROUPS * 16 + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE;
    const auto    h_group  = [&](int it) {
        return 2 + min((tid + it * Config::BLOCK_SIZE) / 16, H_GROUPS - 1);
    };
    // the slots' experts, lane l holding slot l + 64 i in ids[i], read out as a scalar
    constexpr int ID_REGS = (1 + NUM_TOKENS * Config::TOP_K + THREADS_PER_WARP - 1) /
                            THREADS_PER_WARP;
    int ids[ID_REGS];
#pragma unroll
    for (int i = 0; i < ID_REGS; ++i) {
        ids[i] = table.ids[min(i * THREADS_PER_WARP + lane, SLOTS_PADDED - 1)];
    }
    const auto expert_id = [&](int r) {
        int id = __builtin_amdgcn_readlane(ids[0], r % THREADS_PER_WARP);
#pragma unroll
        for (int i = 1; i < ID_REGS; ++i) {
            const int other = __builtin_amdgcn_readlane(ids[i], r % THREADS_PER_WARP);
            id              = r >= i * THREADS_PER_WARP ? other : id;
        }
        return id;
    };
    // Buffer loads at this lane's offsets into an expert's weights and e8m0, the expert's own as a
    // scalar offset
    constexpr int NT      = 2; // the cache-policy operand's nt bit
    const auto    weights = raw_buffer(p.weight, (Config::NUM_EXPERTS + 1) * DOWN_EXPERT_BYTES);
    const auto    scales =
        raw_buffer(p.weight_scale, (Config::NUM_EXPERTS + 1) * DOWN_EXPERT_SCALE_BYTES);

    // the staged experts, wave w loading experts w, w + 4, ...: the full group's (waves 0 and 1's)
    // two K blocks, the half group's (waves 2 and 3's) 8 rows of both, and both groups' e8m0
    if constexpr (EARLY_DMA<NUM_TOKENS>) {
        // past the early slots, staged as they were (stage_expert)
        publish();
        const int staged = min(count, STAGED);
        for (int r = EARLY_SLOTS + wave; r < staged; r += WAVES) {
            stage_expert<NUM_TOKENS>(p, s, r, __builtin_amdgcn_readlane(ids[0], r));
        }
    } else {
        const int full      = split_group(0);
        const int half      = split_group(2);
        const int half_row  = split_row(2, lane);
        const int full_tile = full * DOWN_GROUP_BYTES + lane * 16;
        const int half_tile = half * DOWN_GROUP_BYTES + lane / 32 * K_BLOCK_BYTES_OF<true> +
                              lane % 32 / 8 * 256 + half_row * 16;
        const int full_e8m0 =
            e8m0_dword<Config::INTERMEDIATE_SIZE / 32>(full * 16 + lane % 16, lane / 16);
        const int half_e8m0 =
            e8m0_dword<Config::INTERMEDIATE_SIZE / 32>(half * 16 + half_row, lane / 16);
        publish();
        const int staged = min(count, STAGED);
        for (int r = wave; r < staged; r += WAVES) {
            const int expert = __builtin_amdgcn_readlane(ids[0], r);
            const int w_at   = expert * DOWN_EXPERT_BYTES;
            const int s_at   = expert * DOWN_EXPERT_SCALE_BYTES;
            load_to_lds_nt16(weights, full_tile, w_at, s.w[0][r]);
            load_to_lds_nt16(weights, full_tile + K_BLOCK_BYTES_OF<true>, w_at, s.w[1][r]);
            load_to_lds_nt16(weights, half_tile, w_at, s.w[2][r]);
            load_to_lds4(scales, full_e8m0, s_at, s.s[r][0]);
            load_to_lds4(scales, half_e8m0, s_at, s.s[r][1]);
        }
    }
    wait();
    float residual[AR_ITEMS<NUM_TOKENS>];
    if constexpr (EARLY_RESIDUAL<NUM_TOKENS>) {
        residual_of<NUM_TOKENS>(p.ar, prior_bits, residual);
    } else {
        all_reduce_residual<NUM_TOKENS>(p.ar, residual);
    }
    // written by other XCDs: sc1 loads, past this XCD's caches, 16 B each
    const auto h_buffer = raw_buffer(p.h, sizeof(bfloat16) * MAX_PAIRS * Config::INTERMEDIATE_SIZE);
    bfloat16   h_regs[H_ITERS][8];
#pragma unroll
    for (int it = 0; it < H_ITERS; ++it) {
        const uint32x4 val =
            buffer_load_sc1(h_buffer, (h_group(it) * 128 + tid % 16 * 8) * sizeof(bfloat16));
        __builtin_memcpy(h_regs[it], &val, 16);
    }

    // the streamed experts: w_e8m0[d] holds lane l's e8m0 (of K 32 (l / 16) on in its tile) in
    // byte 0, loaded alone: byte shift / 8 of a staged expert's s dword. Shifting a loaded dword
    // instead puts a VALU use of each load where the compiler hoists it, the top of the loop,
    // which then waits for nearly all of them. Their first loads go out between the staged
    // experts, an expert's after every second (past count they load the last expert again): 32
    // loads in a row stall a wave ~1.2 us, as only ~32 KB a CU go out at once. They are fenced
    // into the order the streamed experts take them, as the reloads are: the compiler's waits in
    // the loop hold for both, so the worse of the two orders would set them.
    const int shift = (kb * 2 + group % 2) * 8;
    const int w_offset =
        group * DOWN_GROUP_BYTES + kb * K_BLOCK_BYTES_OF<true> + lane / 16 * 256 + row * 16;
    const int s_offset =
        e8m0_dword<Config::INTERMEDIATE_SIZE / 32>(group * 16 + row, 4 * kb + lane / 16) +
        shift / 8;
    int32x4    w[DOWN_DEPTH];
    int        w_e8m0[DOWN_DEPTH];
    const auto load_w = [&](int d, int r) {
        const int expert = expert_id(min(r, count - 1));
        w_e8m0[d]        = __builtin_amdgcn_raw_buffer_load_b8(scales, s_offset,
                                                               expert * DOWN_EXPERT_SCALE_BYTES, 0);
        w[d] = __builtin_bit_cast(int32x4, __builtin_amdgcn_raw_buffer_load_b128(
                                               weights, w_offset, expert * DOWN_EXPERT_BYTES, NT));
    };
    // sched_barrier: VALU, SALU, DS reads and TRANS cross it; MFMAs, VMEM and DS writes keep their
    // order around it
    constexpr int ALU_AND_LDS_READS = 0x506;

    // pair 0's h: fp4 zeros (at any scale), so a (slot, token) no token picked adds 0
    if (tid < H_ROW / 16) {
        reinterpret_cast<uint32x4 *>(s.h)[tid] = uint32x4{};
    }
    // group g's row and K block
    const auto h_at = [&](int g) { return s.h + g / 2 * H_ROW + g % 2 * 64; };
    // unconditional: skipping the groups past the pairs lets the compiler move their reads behind
    // the weights' and wait for all of them
    int      h_e8m0[H_ITERS];
    uint32_t range = 0;
#pragma unroll
    for (int it = 0; it < H_ITERS; ++it) {
        h_e8m0[it] = quant_mxfp4_fast(h_regs[it], h_at(h_group(it)) + tid % 16 * 4, range);
    }
    if (quant_range_out(range)) {
#pragma unroll
        for (int it = 0; it < H_ITERS; ++it) {
            h_e8m0[it] = quant_mxfp4(h_regs[it], h_at(h_group(it)) + tid % 16 * 4);
        }
    }

    // kept out of the quant loop so that loop has no branches
    if (tid % 4 == 0) {
#pragma unroll
        for (int it = 0; it < H_ITERS; ++it) {
            const int g = h_group(it);
            s.h[g / 2 * H_ROW + H_E8M0 + g % 2 * 4 + tid % 16 / 4] = h_e8m0[it];
        }
    }
    block_sync_lds();

    // columns past M repeat token M - 1 and are dropped; this lane's token's pairs and weights
    const int      token    = min(lane % 16, NUM_TOKENS - 1);
    const uint8_t *my_pairs = pairs + token * SLOTS_PADDED;
    const float   *my_w     = table.w[token];
    // this lane's 16 B of a pair's K block and its e8m0, from the pair's row
    const int      h_lane   = kb * 64 + lane / 16 * 16;
    const int      e_lane   = H_E8M0 + kb * 4 + lane / 16;
    floatx4        acc      = {};
    // the scales go into the instruction, the routing weight onto its result
    const auto expert = [&](const int32x4 &w, int w_e8m0, uint32_t pair, float weight) {
        const uint8_t *at = s.h + pair * H_ROW;
        const int32x4  h  = *reinterpret_cast<const int32x4 *>(at + h_lane);
        acc += mfma_16x16x128_fp4(w, h, w_e8m0, at[e_lane]) * weight;
    };
    // run(d, pair, weight) for the round of experts r0 .. r0 + 7, from this lane's token's pairs
    // and weights, 8 bytes and 8 floats
    static_assert(DOWN_ROUND == 8);
    const auto round = [&](int r0, const auto &run) {
        const uint2   pr = *reinterpret_cast<const uint2 *>(my_pairs + r0);
        const floatx4 wa = *reinterpret_cast<const floatx4 *>(my_w + r0);
        const floatx4 wb = *reinterpret_cast<const floatx4 *>(my_w + r0 + 4);
#pragma unroll
        for (int d = 0; d < DOWN_ROUND; ++d) {
            run(d, (d < 4 ? pr.x : pr.y) >> d % 4 * 8 & 0xffu, d < 4 ? wa[d] : wb[d - 4]);
        }
    };

    // staged expert r: this wave's K block at tile + 1 KB r, its lane's e8m0 dword at e8m0 + 512 r;
    // EARLY_DMA: at tile_in and e8m0_in of the expert's slot
    const int      tile_in = wave < 2 ? kb * K_BLOCK_BYTES_OF<true> + lane * 16
                                      : 2 * K_BLOCK_BYTES_OF<true> + kb * 512 + lane / 16 * 128 + lane % 8 * 16;
    const int      e8m0_in = 3 * K_BLOCK_BYTES_OF<true> + (wave / 2 * THREADS_PER_WARP + lane) * 4;
    const uint8_t *tile = wave < 2 ? s.w[kb][0] + lane * 16
                                   : s.w[2][0] + kb * 512 + lane / 16 * 128 + lane % 8 * 16;
    const uint8_t *e8m0 = reinterpret_cast<const uint8_t *>(&s.s[0][wave / 2][lane]);
    const auto staged_expert = [&](int r, uint32_t pair, float weight) {
        if constexpr (EARLY_DMA<NUM_TOKENS>) {
            const uint8_t *slot = slot_base(s, r);
            expert(*reinterpret_cast<const int32x4 *>(slot + tile_in),
                   *reinterpret_cast<const int *>(slot + e8m0_in) >> shift, pair, weight);
        } else {
            const int s_e8m0 =
                *reinterpret_cast<const int *>(e8m0 + r * 2 * THREADS_PER_WARP * sizeof(uint32_t));
            expert(*reinterpret_cast<const int32x4 *>(tile + r * K_BLOCK_BYTES_OF<true>),
                   s_e8m0 >> shift, pair, weight);
        }
    };
    // the streamed experts, a step of two rounds at a time while experts remain past it, each
    // reloading its w with the expert DOWN_DEPTH on, then the last 1 .. DOWN_DEPTH without
    // reloads. Past count a slot's pair and routing weight are 0 and its w the last expert's,
    // which adds exactly 0; loading them keeps every round's load count fixed for the compiler.
    // Each MFMA waits only for loads DOWN_DEPTH experts old as: the loop leaves only after a
    // whole step (with an exit between its rounds, the compiler's waits in the first take the
    // second as maybe not run); both rounds' slots are used past the loop (else the compiler
    // narrows the second's to bytes, to widen again at the loop's top: a wait there for its
    // loads); and fences keep each expert's MFMA, then its reload, in program order (else the
    // MFMAs bunch ahead of the reloads).
    static_assert(DOWN_DEPTH == 2 * DOWN_ROUND);
    const auto streamed_round = [&](int base, int k, auto reload) {
        round(base + k * DOWN_ROUND, [&](int d, uint32_t pair, float weight) {
            const int j = k * DOWN_ROUND + d;
            expert(w[j], w_e8m0[j], pair, weight);
            if constexpr (reload) {
                __builtin_amdgcn_sched_barrier(ALU_AND_LDS_READS);
                load_w(j, base + j + DOWN_DEPTH);
                __builtin_amdgcn_sched_barrier(ALU_AND_LDS_READS);
            }
        });
    };
    if (count > STAGED) {
        // every staged round full; expert j's first loads go out after staged expert 2 j + 1
        static_assert(STAGED == 2 * DOWN_DEPTH);
#pragma unroll
        for (int r0 = 0; r0 < STAGED; r0 += DOWN_ROUND) {
            round(r0, [&](int d, uint32_t pair, float weight) {
                staged_expert(r0 + d, pair, weight);
                if (d % 2 == 1) {
                    __builtin_amdgcn_sched_barrier(ALU_AND_LDS_READS);
                    load_w((r0 + d) / 2, STAGED + (r0 + d) / 2);
                    __builtin_amdgcn_sched_barrier(ALU_AND_LDS_READS);
                }
            });
        }
        // never taken (count >= 0): a use of each byte in its load's block keeps its zero-extension
        // folded into the load; sunk to where the loop and the last rounds meet, it is an AND there
        // that waits for nearly all of these loads
        if (count < 0) {
#pragma unroll
            for (int d = 0; d < DOWN_DEPTH; ++d) {
                asm volatile("" ::"v"(w_e8m0[d]));
            }
        }
        int r0 = STAGED;
        for (; r0 + DOWN_DEPTH < count; r0 += DOWN_DEPTH) {
            streamed_round(r0, 0, std::true_type{});
            streamed_round(r0, 1, std::true_type{});
        }
        if (r0 < count) {
            streamed_round(r0, 0, std::false_type{});
        }
        if (r0 + DOWN_ROUND < count) {
            streamed_round(r0, 1, std::false_type{});
        }
    } else {
        // the staged experts alone; past them LDS holds anything (an e8m0 of 255 is NaN): the
        // last round takes only its own
        int r0 = 0;
        for (; r0 + DOWN_ROUND <= count; r0 += DOWN_ROUND) {
            round(r0,
                  [&](int d, uint32_t pair, float weight) { staged_expert(r0 + d, pair, weight); });
        }
        if (r0 < count) {
            round(r0, [&](int d, uint32_t pair, float weight) {
                if (r0 + d < count) {
                    staged_expert(r0 + d, pair, weight);
                }
            });
        }
    }

    all_reduce_rows<NUM_TOKENS>(p.ar, s.rows, acc, call, residual);
}

// gate_up's partial sums after the top-k's: it reads x into registers as it starts
constexpr int SMEM_GATE_UP_OFFSET = SMEM_TOPK_END;
static_assert(SMEM_GATE_UP_OFFSET + SMEM_GATE_UP_SIZE <= Config::SMEM_SIZE);

// Past 8 tokens the stream's last slice (each thread's last 16 B of a row) goes to LDS raw as it
// lands, registers holding the others (all of them would not fit): [M][X2_ROW] over gate_up's
// partial sums, which come after the top-k
template <int NUM_TOKENS> constexpr bool X2_LDS = NUM_TOKENS > 8;
constexpr int X2_ROW         = Config::BLOCK_SIZE * 8;
constexpr int SMEM_X2_OFFSET = SMEM_GATE_UP_OFFSET;
static_assert(SMEM_X2_OFFSET + Config::MAX_NUM_TOKENS * X2_ROW * sizeof(bfloat16) <=
              Config::SMEM_SIZE);

// What the MoE reads besides h: gamma and block b's router row (expert b's), at its start
// (load_front), and lane l's router biases (experts 4l .. 4l + 3), past the router
struct MoeFront {
    bfloat16 gamma[ROW_LOADS][8];
    bfloat16 router[ROW_LOADS][8];
    float    bias[Config::NUM_EXPERTS / THREADS_PER_WARP];
};
__device__ __forceinline__ void load_front(const MoeParams &p, MoeFront &f) {
    const int tid = threadIdx.x;
#pragma unroll
    for (int i = 0; i < ROW_LOADS; ++i) {
        load_data<bfloat16, 8>(p.gamma + (i * Config::BLOCK_SIZE + tid) * 8, f.gamma[i]);
    }
#pragma unroll
    for (int i = 0; i < ROW_LOADS; ++i) {
        load_data<bfloat16, 8>(
            p.router_weight + blockIdx.x * Config::HIDDEN_SIZE + (i * Config::BLOCK_SIZE + tid) * 8,
            f.router[i]);
    }
}

// quant_rows<NUM_TOKENS, ROW_LOADS, true> (common/math.h) of x into q and scales, by
// quant_mxfp4_fast unless a group of this wave's is out of its range. mid() runs once the groups of
// the first MID tokens (half of them, rounded up to the QUANT_TOKENS step) are done.
template <int NUM_TOKENS, typename Mid>
__device__ __forceinline__ void quant_x(const bfloat16 (&x)[NUM_TOKENS][ROW_LOADS][8], uint8_t *q,
                                        uint8_t *scales, Mid mid) {
    const int  tid    = threadIdx.x;
    // this lane's group of slice i of token m: codes at q_lane + offset(m, i) / 2, e8m0 at
    // s_lane + offset(m, i) / 32, the constants going into the LDS instructions' offsets
    uint8_t *const q_lane = q + tid * 4;
    uint8_t *const s_lane = scales + tid / 4;
    const auto     offset = [](int m, int i) {
        return m * Config::HIDDEN_SIZE + i * Config::BLOCK_SIZE * 8;
    };
    int      e8m0[NUM_TOKENS][ROW_LOADS];
    uint32_t range = 0;
    // QUANT_TOKENS tokens' groups at a time, side by side
    constexpr int QUANT_TOKENS = NUM_TOKENS % 2 == 0 ? 2 : 1;
    constexpr int B   = QUANT_TOKENS * ROW_LOADS;
    // at least the first step: one token's (M = 1) halfway is past its only one
    constexpr int MID_ = (NUM_TOKENS / 2 + QUANT_TOKENS - 1) / QUANT_TOKENS * QUANT_TOKENS;
    constexpr int MID  = MID_ > QUANT_TOKENS ? MID_ : QUANT_TOKENS;
#pragma unroll
    for (int m0 = 0; m0 < NUM_TOKENS; m0 += QUANT_TOKENS) {
        bfloat16 v[B][8];
        uint8_t *at[B];
        int      e[B];
#pragma unroll
        for (int b = 0; b < B; ++b) {
            __builtin_memcpy(v[b], x[m0 + b / ROW_LOADS][b % ROW_LOADS], 16);
            at[b] = q_lane + offset(m0 + b / ROW_LOADS, b % ROW_LOADS) / 2;
        }
        quant_mxfp4_fast_n(v, at, e, range);
#pragma unroll
        for (int b = 0; b < B; ++b) {
            e8m0[m0 + b / ROW_LOADS][b % ROW_LOADS] = e[b];
        }
        if (m0 + QUANT_TOKENS == MID) {
            mid();
        }
    }
    if (quant_range_out(range)) {
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < ROW_LOADS; ++i) {
                e8m0[m][i] = quant_mxfp4(x[m][i], q_lane + offset(m, i) / 2);
            }
        }
    }
    // not inside the loops above: a branch there would serialize the groups
    if (tid % 4 == 0) {
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < ROW_LOADS; ++i) {
                s_lane[offset(m, i) / 32] = e8m0[m][i];
            }
        }
    }
}

// rms_norm_route (aklr/router.h) on block_reduce_n: the same bits
template <int NUM_TOKENS>
__device__ __forceinline__ void rms_norm_route_n(bfloat16 (&x)[NUM_TOKENS][ROW_LOADS][8],
                                                 const bfloat16 (&gamma)[ROW_LOADS][8],
                                                 const bfloat16 (&w)[ROW_LOADS][8], float eps,
                                                 float *reduce, float (&logits)[NUM_TOKENS]) {
    constexpr int N = ROW_LOADS * 8 * Config::BLOCK_SIZE;
    float         sums[NUM_TOKENS];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        floatx2 sum2 = {};
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            add_squares(sum2, x[m][i]);
        }
        sums[m] = sum2.x + sum2.y;
    }
    block_reduce_n<SumOp, false>(sums, reduce);
    floatx2 gw[ROW_LOADS][4];
#pragma unroll
    for (int i = 0; i < ROW_LOADS; ++i) {
        gamma_router(gamma[i], w[i], gw[i]);
    }
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        const float factor = rsqrtf(sums[m] / N + eps);
        floatx2     acc    = {};
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            norm_route(x[m][i], gamma[i], gw[i], factor, acc);
            pin_row(x[m][i]);
        }
        logits[m] = route_sum(acc, factor);
    }
}

// SPLIT_NORM: rms_norm_route_n's logits alone, x left raw and each token's norm factor out:
// normalize_x then takes x as rms_norm_route_n leaves it, past the logits' publish. The same
// floats and order as rms_norm_route_n's, so the same bits.
template <int NUM_TOKENS> constexpr bool SPLIT_NORM = NUM_TOKENS == 4 || NUM_TOKENS == 8;
template <int NUM_TOKENS>
__device__ __forceinline__ void route_logits_n(const bfloat16 (&x)[NUM_TOKENS][ROW_LOADS][8],
                                               const bfloat16 (&gamma)[ROW_LOADS][8],
                                               const bfloat16 (&w)[ROW_LOADS][8], float eps,
                                               float *reduce, float (&logits)[NUM_TOKENS],
                                               float (&factors)[NUM_TOKENS]) {
    constexpr int N = ROW_LOADS * 8 * Config::BLOCK_SIZE;
    // the squares and the router dots in one pass over x's floats (each in its own order, as
    // add_squares and norm_route take them), the dots' factor applied past the squares' reduce
    floatx2 gw[ROW_LOADS][4];
#pragma unroll
    for (int i = 0; i < ROW_LOADS; ++i) {
        gamma_router(gamma[i], w[i], gw[i]);
    }
    float   sums[NUM_TOKENS];
    floatx2 accs[NUM_TOKENS];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        floatx2 sum2 = {};
        floatx2 acc  = {};
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x[m][i]);
#pragma unroll
            for (int j = 0; j < 4; ++j) {
                const floatx2 v = to_float2(x2[j]);
                sum2 += v * v;
                acc = __builtin_elementwise_fma(v, gw[i][j], acc);
            }
        }
        sums[m] = sum2.x + sum2.y;
        accs[m] = acc;
    }
    // the sums' block reduce, LDS alone, its scratch not reused (the logits' reduce has its own)
    block_reduce_n_once<SumOp>(sums, reduce);
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        factors[m] = rsqrtf(sums[m] / N + eps);
        logits[m]  = route_sum(accs[m], factors[m]);
    }
}
// x normed in place as norm_route does it (bf16(x factor gamma)), by the factors route_logits_n gave
template <int NUM_TOKENS>
__device__ __forceinline__ void normalize_x(bfloat16 (&x)[NUM_TOKENS][ROW_LOADS][8],
                                            const bfloat16 (&gamma)[ROW_LOADS][8],
                                            const float (&factors)[NUM_TOKENS]) {
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            auto       *x2 = reinterpret_cast<bfloat16x2 *>(x[m][i]);
            const auto *g2 = reinterpret_cast<const bfloat16x2 *>(gamma[i]);
#pragma unroll
            for (int j = 0; j < 4; ++j) {
                x2[j] = to_bf16x2(to_float2(x2[j]) * factors[m] * to_float2(g2[j]));
            }
        }
    }
}

// Past 8 tokens (X2_LDS): x as REGS slices in registers and the last in LDS at x2, raw. Runs
// rms_norm_route (aklr/router.h) in its order over registers alone, x left normalized, the last
// slice in place in LDS.
template <int NUM_TOKENS, int REGS>
__device__ __forceinline__ void norm_router_x2(bfloat16 (&x)[NUM_TOKENS][REGS][8], bfloat16 *x2,
                                               const MoeFront &f, float eps, float *reduce,
                                               float (&logits)[NUM_TOKENS]) {
    static_assert(REGS == ROW_LOADS - 1);
    constexpr int N   = ROW_LOADS * 8 * Config::BLOCK_SIZE;
    const int     tid = threadIdx.x;
    const auto    at  = [&](int m) { return reinterpret_cast<uint32x4 *>(x2 + m * X2_ROW + tid * 8); };
    // the register slices' squares first: the compiler waits for each token's loads as it goes
    floatx2 sum2[NUM_TOKENS];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        sum2[m] = {};
#pragma unroll
        for (int i = 0; i < REGS; ++i) {
            add_squares(sum2[m], x[m][i]);
        }
    }
    // the last slice comes by DMA, which the compiler does not wait for
    asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
    float sums[NUM_TOKENS];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        bfloat16 raw[8];
        *reinterpret_cast<uint32x4 *>(raw) = *at(m);
        add_squares(sum2[m], raw);
        sums[m] = sum2[m].x + sum2[m].y;
    }
    block_reduce_n<SumOp, false>(sums, reduce);
    floatx2 gw[ROW_LOADS][4];
#pragma unroll
    for (int i = 0; i < ROW_LOADS; ++i) {
        gamma_router(f.gamma[i], f.router[i], gw[i]);
    }
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        const float factor = rsqrtf(sums[m] / N + eps);
        floatx2     acc    = {};
#pragma unroll
        for (int i = 0; i < REGS; ++i) {
            norm_route(x[m][i], f.gamma[i], gw[i], factor, acc);
            pin_row(x[m][i]);
        }
        bfloat16 raw[8];
        *reinterpret_cast<uint32x4 *>(raw) = *at(m);
        norm_route(raw, f.gamma[REGS], gw[REGS], factor, acc);
        *at(m)    = __builtin_bit_cast(uint32x4, raw);
        logits[m] = route_sum(acc, factor);
    }
}

// quant_x of x as norm_router_x2 leaves it, mid() as quant_x's
template <int NUM_TOKENS, int REGS, typename Mid>
__device__ __forceinline__ void quant_x2(const bfloat16 (&x)[NUM_TOKENS][REGS][8],
                                         const bfloat16 *x2, uint8_t *q, uint8_t *scales,
                                         Mid mid) {
    const int  tid    = threadIdx.x;
    // this lane's group of slice i of token m: codes at q_lane + offset(m, i) / 2, e8m0 at
    // s_lane + offset(m, i) / 32, the constants going into the LDS instructions' offsets
    uint8_t *const q_lane = q + tid * 4;
    uint8_t *const s_lane = scales + tid / 4;
    const auto     offset = [](int m, int i) {
        return m * Config::HIDDEN_SIZE + i * Config::BLOCK_SIZE * 8;
    };
    const auto values = [&](int m, int i, bfloat16(&v)[8]) {
        if (i < REGS) {
            __builtin_memcpy(v, x[m][i < REGS ? i : 0], 16);
        } else {
            *reinterpret_cast<uint32x4 *>(v) =
                *reinterpret_cast<const uint32x4 *>(x2 + m * X2_ROW + tid * 8);
        }
    };
    int      e8m0[NUM_TOKENS][ROW_LOADS];
    uint32_t range = 0;
    // QUANT_TOKENS tokens' groups at a time, side by side
    constexpr int QUANT_TOKENS = NUM_TOKENS % 2 == 0 ? 2 : 1;
    constexpr int B   = QUANT_TOKENS * ROW_LOADS;
    constexpr int MID = (NUM_TOKENS / 2 + QUANT_TOKENS - 1) / QUANT_TOKENS * QUANT_TOKENS;
#pragma unroll
    for (int m0 = 0; m0 < NUM_TOKENS; m0 += QUANT_TOKENS) {
        bfloat16 v[B][8];
        uint8_t *at[B];
        int      e[B];
#pragma unroll
        for (int b = 0; b < B; ++b) {
            values(m0 + b / ROW_LOADS, b % ROW_LOADS, v[b]);
            at[b] = q_lane + offset(m0 + b / ROW_LOADS, b % ROW_LOADS) / 2;
        }
        quant_mxfp4_fast_n(v, at, e, range);
#pragma unroll
        for (int b = 0; b < B; ++b) {
            e8m0[m0 + b / ROW_LOADS][b % ROW_LOADS] = e[b];
        }
        if (m0 + QUANT_TOKENS == MID) {
            mid();
        }
    }
    if (quant_range_out(range)) {
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < ROW_LOADS; ++i) {
                bfloat16 v[8];
                values(m, i, v);
                e8m0[m][i] = quant_mxfp4(v, q_lane + offset(m, i) / 2);
            }
        }
    }
    if (tid % 4 == 0) {
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < ROW_LOADS; ++i) {
                s_lane[offset(m, i) / 32] = e8m0[m][i];
            }
        }
    }
}

// The MoE layer's work on this block, at this call's epoch, last_call its all-reduce's last call
// number (as row_linear_ar_block's).
template <int NUM_TOKENS>
__device__ __forceinline__ void moe_block(const MoeParams &p, uint8_t *smem, uint32_t epoch,
                                          uint32_t last_call) {
    constexpr int HIDDEN_SIZE = Config::HIDDEN_SIZE;
    constexpr int BLOCK_SIZE  = Config::BLOCK_SIZE;

    const int bid = blockIdx.x;
    const int tid = threadIdx.x;

    uint32x4 *slots   = static_cast<uint32x4 *>(p.workspace);
    uint32x4 *my_slot = slots + bid * PACKETS_PER_SLOT;

    constexpr bool X2   = X2_LDS<NUM_TOKENS>;
    constexpr int  REGS = X2 ? ROW_LOADS - 1 : ROW_LOADS;
    bfloat16       x_regs[NUM_TOKENS][REGS][8];
    bfloat16      *x2 = reinterpret_cast<bfloat16 *>(smem + SMEM_X2_OFFSET);
    MoeFront       f;
    if constexpr (X2) {
        // lane l's 16 B land at 16 l of its wave's KB
        const auto stream = raw_buffer(p.h, NUM_TOKENS * HIDDEN_SIZE * sizeof(bfloat16));
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
            load_to_lds16(stream, (REGS * BLOCK_SIZE + tid) * 16, m * HIDDEN_SIZE * 2,
                          x2 + m * X2_ROW + tid / THREADS_PER_WARP * THREADS_PER_WARP * 8);
        }
    }
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
        for (int i = 0; i < REGS; ++i) {
            load_data<bfloat16, 8>(p.h + m * HIDDEN_SIZE + (i * BLOCK_SIZE + tid) * 8,
                                   x_regs[m][i]);
        }
    }
    // block b computes the router logits of expert b
    static_assert(Config::NUM_BLOCKS == Config::NUM_EXPERTS);
    load_front(p, f);
    uint16_t prior_bits[AR_ITEMS<NUM_TOKENS>] = {};
    if constexpr (EARLY_RESIDUAL<NUM_TOKENS>) {
        residual_bits<NUM_TOKENS>(p.down.ar, prior_bits);
    }
    // for the top-k, lane l scores experts l*EXPERTS_PER_LANE onward
    constexpr int EXPERTS_PER_LANE = Config::NUM_EXPERTS / THREADS_PER_WARP;
    static_assert(EXPERTS_PER_LANE == 4);
    const int warp_id = tid / THREADS_PER_WARP;
    const int lane_id = tid % THREADS_PER_WARP;

    // router as the op's fp32 reference: logits = F.linear(y, W.float()) on y, the norm's fp32
    // output before x takes it rounded, accumulated in fp32
    float router_logits[NUM_TOKENS];
    float norm_factors[NUM_TOKENS]; // SPLIT_NORM
    if constexpr (X2) {
        norm_router_x2<NUM_TOKENS>(x_regs, x2, f, p.epsilon,
                                   reinterpret_cast<float *>(smem + SMEM_REDUCE_OFFSET),
                                   router_logits);
    } else if constexpr (SPLIT_NORM<NUM_TOKENS>) {
        route_logits_n<NUM_TOKENS>(x_regs, f.gamma, f.router, p.epsilon,
                                   reinterpret_cast<float *>(smem + SMEM_REDUCE_OFFSET),
                                   router_logits, norm_factors);
    } else {
        rms_norm_route_n<NUM_TOKENS>(x_regs, f.gamma, f.router, p.epsilon,
                                     reinterpret_cast<float *>(smem + SMEM_REDUCE_OFFSET),
                                     router_logits);
    }
    if constexpr (SPLIT_NORM<NUM_TOKENS>) {
        // its own scratch (gate_up's partial sums', unused this early), so one sync
        block_reduce_n_once<SumOp>(router_logits, reinterpret_cast<float *>(smem + SMEM_GATE_UP_OFFSET));
    } else {
        block_reduce_n<SumOp>(router_logits, reinterpret_cast<float *>(smem + SMEM_REDUCE_OFFSET));
    }

    // sync (1), publish: logits and epoch go out in one 16 B store, so a reader that sees the
    // epoch also sees the logits
    constexpr int NUM_PACKETS = (NUM_TOKENS + 2) / 3;
    static_assert(NUM_PACKETS <= LOGIT_PACKETS);
    if (tid == 0) {
        float vals[3 * NUM_PACKETS] = {};
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
            vals[m] = router_logits[m];
        }
#pragma unroll
        for (int k = 0; k < NUM_PACKETS; ++k) {
            const uint32x4 packet = {__float_as_uint(vals[3 * k]), __float_as_uint(vals[3 * k + 1]),
                                     __float_as_uint(vals[3 * k + 2]), epoch};
            store_sc1(p.logits + bid * LOGIT_PACKETS + k, packet);
        }
    }

    // the top-k's biases: loaded past the router, which needs every register it can get, and landed
    // by the gather
    load_data<float, 4>(p.router_bias + lane_id * 4, f.bias);

    // sync (1)'s first round: thread t loads block t's packets halfway through the quant, which
    // runs longer than the publishes' spread, and the rest of the quant and the zeroing hide the
    // round trip. Compiler-visible loads, so the compiler waits for them where they are read.
    static_assert(Config::NUM_BLOCKS == BLOCK_SIZE);
    // p.logits read first-lane: past the publish's branch the compiler takes it as divergent, and a
    // buffer resource made from it then has it loop over the lanes for every load
    const auto     bits = reinterpret_cast<uintptr_t>(p.logits);
    const uint32_t lo   = __builtin_amdgcn_readfirstlane(static_cast<uint32_t>(bits));
    const uint32_t hi   = __builtin_amdgcn_readfirstlane(static_cast<uint32_t>(bits >> 32));
    const auto     packet_buffer = raw_buffer(
        reinterpret_cast<const void *>(static_cast<uintptr_t>(hi) << 32 | lo), LOGITS_SIZE);
    uint32x4   packets[NUM_PACKETS];
    const auto first_round   = [&] {
        // between the halves' LDS stores
        asm volatile("" ::: "memory");
#pragma unroll
        for (int k = 0; k < NUM_PACKETS; ++k) {
            packets[k] = buffer_load_sc1(packet_buffer, (tid * LOGIT_PACKETS + k) * 16);
        }
        asm volatile("" ::: "memory");
    };

    // x quant for the expert GEMMs: MXFP4, an e8m0 per 32
    uint8_t *x_q = smem + SMEM_X_OFFSET;
    uint8_t *x_s = smem + SMEM_X_SCALE_OFFSET;
    if constexpr (X2) {
        quant_x2<NUM_TOKENS>(x_regs, x2, x_q, x_s, first_round);
    } else {
        if constexpr (SPLIT_NORM<NUM_TOKENS>) {
            normalize_x<NUM_TOKENS>(x_regs, f.gamma, norm_factors);
        }
        quant_x<NUM_TOKENS>(x_regs, x_q, x_s, first_round);
    }

    // zero the table, the pairs and the mask: LDS starts with garbage, the top-k ORs its picks into
    // the mask, the grouping writes only the picked slots and the weights and pairs of tokens that
    // picked them, and gate_up reads the ids of every slot it might take
    constexpr int ZERO_TURNS = (SMEM_ZEROED_SIZE / 16 + BLOCK_SIZE - 1) / BLOCK_SIZE;
#pragma unroll
    for (int k = 0; k < ZERO_TURNS; ++k) {
        const int i = tid + k * BLOCK_SIZE;
        if (i < SMEM_ZEROED_SIZE / 16) {
            reinterpret_cast<uint32x4 *>(smem + SMEM_TABLE_OFFSET)[i] = uint32x4{};
        }
    }

    // sync (1), gather after the quant so other blocks have had time to publish: thread t waits
    // for block t's packets of this epoch, the first round's read here (the pins: its wait lands
    // past the zeroing), then polled again while any is stale
    float     *logits = reinterpret_cast<float *>(smem + SMEM_LOGITS_OFFSET);
    const auto stale  = [&] {
        bool ready = true;
#pragma unroll
        for (int k = 0; k < NUM_PACKETS; ++k) {
            ready = ready && packets[k][3] == epoch;
        }
        return !ready;
    };
#pragma unroll
    for (int k = 0; k < NUM_PACKETS; ++k) {
        pin(packets[k]);
    }
    while (stale()) {
        load_packets_sc1(p.logits + tid * LOGIT_PACKETS, packets);
    }
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        logits[m * Config::NUM_EXPERTS + tid] = __uint_as_float(packets[m / 3][m % 3]);
    }
    __syncthreads();

    // top-k as in HF noaux_tc (n_group = topk_group = 1): wave w picks the experts of tokens w,
    // w + 4, ... side by side, by sigmoid(logit) + bias, one wave-wide max per pick; ties go to the
    // lower expert id. Past M a wave repeats token M - 1 and drops it.
    constexpr int TOKENS_PER_WAVE = (NUM_TOKENS + WAVES - 1) / WAVES;
    int          *topk_ids        = reinterpret_cast<int *>(smem + SMEM_TOPK_IDS_OFFSET);
    float        *topk_w          = reinterpret_cast<float *>(smem + SMEM_TOPK_W_OFFSET);
    uint32_t     *picked_mask     = reinterpret_cast<uint32_t *>(smem + SMEM_PICKED_MASK_OFFSET);
    {
        const float *token_logits[TOKENS_PER_WAVE];
#pragma unroll
        for (int t = 0; t < TOKENS_PER_WAVE; ++t) {
            token_logits[t] =
                logits + min(warp_id + t * WAVES, NUM_TOKENS - 1) * Config::NUM_EXPERTS;
        }
        // this lane's experts, sorted by key and then e, so a pick only compares the lanes' heads
        // and only the picked lane moves on; ties go to the lowest lane, so the lowest expert id
        uint32_t key[TOKENS_PER_WAVE][EXPERTS_PER_LANE];
        int      eid[TOKENS_PER_WAVE][EXPERTS_PER_LANE];
#pragma unroll
        for (int t = 0; t < TOKENS_PER_WAVE; ++t) {
#pragma unroll
            for (int e = 0; e < EXPERTS_PER_LANE; ++e) {
                const float logit = token_logits[t][lane_id * EXPERTS_PER_LANE + e];
                key[t][e]         = ordered_bits(sigmoid(logit) + f.bias[e]);
                eid[t][e]         = e;
            }
        }
        const auto order = [&](int t, int a, int b) {
            // bitwise, not short-circuit: no branches
            const bool     swap = (key[t][b] > key[t][a]) |
                              ((key[t][b] == key[t][a]) & (eid[t][b] < eid[t][a]));
            const uint32_t ka   = key[t][a];
            const int      ea   = eid[t][a];
            key[t][a]           = swap ? key[t][b] : ka;
            eid[t][a]           = swap ? eid[t][b] : ea;
            key[t][b]           = swap ? ka : key[t][b];
            eid[t][b]           = swap ? ea : eid[t][b];
        };
        static_assert(EXPERTS_PER_LANE == 4);
#pragma unroll
        for (int t = 0; t < TOKENS_PER_WAVE; ++t) {
            order(t, 0, 1);
            order(t, 2, 3);
            order(t, 0, 2);
            order(t, 1, 3);
            order(t, 1, 2);
        }
        // lane k ends with pick k's expert id, the others with 0
        int pick_id[TOKENS_PER_WAVE] = {};
#pragma unroll
        for (int k = 0; k < Config::TOP_K; ++k) {
            // the tokens' wave-wide maxes side by side
            uint32_t best[TOKENS_PER_WAVE];
#pragma unroll
            for (int t = 0; t < TOKENS_PER_WAVE; ++t) {
                best[t] = key[t][0];
            }
            warp_reduce_n<MaxOp>(best);
#pragma unroll
            for (int t = 0; t < TOKENS_PER_WAVE; ++t) {
                const int      lane   = __builtin_ctzll(__ballot(key[t][0] == best[t]));
                const int      id     = lane * EXPERTS_PER_LANE + readlane(eid[t][0], lane);
                pick_id[t]            = lane_id == k ? id : pick_id[t];
                const bool     picked = lane_id == lane;
#pragma unroll
                for (int e = 0; e + 1 < EXPERTS_PER_LANE; ++e) {
                    key[t][e] = picked ? key[t][e + 1] : key[t][e];
                    eid[t][e] = picked ? eid[t][e + 1] : eid[t][e];
                }
                key[t][EXPERTS_PER_LANE - 1] = picked ? 0 : key[t][EXPERTS_PER_LANE - 1];
            }
        }
        // weights as in HF: sigmoid without the bias, normalized, then scaled. Lane k scores pick k
        // and the sum adds the lanes' scores in pick order, as HF's adds the picks'; lane k keeps
        // pick k, so the stores and the mask OR below are one LDS instruction each for all 8 picks
        float score[TOKENS_PER_WAVE], sum[TOKENS_PER_WAVE];
#pragma unroll
        for (int t = 0; t < TOKENS_PER_WAVE; ++t) {
            score[t] = sigmoid(token_logits[t][pick_id[t]]);
            sum[t]   = 0.0f;
        }
#pragma unroll
        for (int k = 0; k < Config::TOP_K; ++k) {
#pragma unroll
            for (int t = 0; t < TOKENS_PER_WAVE; ++t) {
                sum[t] += readlane(score[t], k);
            }
        }
#pragma unroll
        for (int t = 0; t < TOKENS_PER_WAVE; ++t) {
            const float norm = __builtin_amdgcn_rcpf(sum[t] + 1e-20f) * p.routed_scaling_factor;
            const int   m    = warp_id + t * WAVES;
            if (m < NUM_TOKENS && lane_id < Config::TOP_K) {
                topk_ids[m * Config::TOP_K + lane_id] = pick_id[t];
                topk_w[m * Config::TOP_K + lane_id]   = score[t] * norm;
                atomicOr(picked_mask + pick_id[t] / 32, 1u << pick_id[t] % 32);
            }
        }
    }
    __syncthreads();

    // EARLY0: this block's first gate_up item (slot xcd: the shared expert on XCD 0, else the xcd-th
    // picked id) found from the picked mask, its weights issued now
    constexpr bool EARLY0 = NUM_TOKENS == 4 || NUM_TOKENS == 8;
    GateUpFirst    first;
    if constexpr (EARLY0) {
        const int xcd = bid % 8;
        int       expert0;
        if (xcd == 0) {
            expert0 = Config::SHARED_EXPERT;
        } else {
            uint32_t m[Config::NUM_EXPERTS / 32];
#pragma unroll
            for (int i = 0; i < Config::NUM_EXPERTS / 32; i += 4) {
                load_data<uint32_t, 4>(picked_mask + i, m + i);
            }
            int need = xcd;
            expert0  = -1;
#pragma unroll
            for (int i = 0; i < Config::NUM_EXPERTS / 32; ++i) {
                const uint32_t mi = __builtin_amdgcn_readfirstlane(m[i]);
                const int      c  = __popc(mi);
                if (expert0 < 0) {
                    if (need <= c) {
                        uint32_t mm = mi;
                        for (int k = 1; k < need; ++k) {
                            mm &= mm - 1u;
                        }
                        expert0 = 32 * i + __builtin_ctz(mm);
                    } else {
                        need -= c;
                    }
                }
            }
        }
        if (expert0 >= 0) {
            gate_up_issue0(p.gate_up_weight, p.gate_up_scale, expert0, first);
        }
    }

    // grouping for the expert GEMMs: the shared expert, then the picked ones in id order, so a
    // pick's slot is 1 + how many picked ids are below it; thread i takes pick i (token i / 8)
    ExpertTable &table = *reinterpret_cast<ExpertTable *>(smem + SMEM_TABLE_OFFSET);
    uint8_t     *pairs = smem + SMEM_PAIRS_OFFSET;
    static_assert(Config::MAX_NUM_TOKENS * Config::TOP_K <= BLOCK_SIZE);
    if (tid < NUM_TOKENS * Config::TOP_K) {
        const int pick_id = topk_ids[tid];
        uint32_t  mask[Config::NUM_EXPERTS / 32];
#pragma unroll
        for (int i = 0; i < Config::NUM_EXPERTS / 32; i += 4) {
            load_data<uint32_t, 4>(picked_mask + i, mask + i);
        }
        int rank  = 0;
        int count = 0;
#pragma unroll
        for (int i = 0; i < Config::NUM_EXPERTS / 32; ++i) {
            const int below = min(max(pick_id - 32 * i, 0), 32);
            rank += __popc(mask[i] & static_cast<uint32_t>((1ull << below) - 1));
            count += __popc(mask[i]);
        }
        const int m                         = tid / Config::TOP_K;
        table.ids[1 + rank]                 = pick_id;
        table.w[m][1 + rank]                = topk_w[tid];
        pairs[m * SLOTS_PADDED + 1 + rank] = 1 + NUM_TOKENS + tid;
        if (tid < Config::MAX_NUM_TOKENS) {
            table.w[tid][0] = 1.0f;
        }
        if (tid < NUM_TOKENS) {
            pairs[tid * SLOTS_PADDED] = 1 + tid; // slot 0's
        }
        table.ids[0] = Config::SHARED_EXPERT;
        table.count  = 1 + count;
    }
    // the grouping; EARLY0: an LDS-only sync, past which the first item's loads stay in flight
    if constexpr (EARLY0) {
        block_sync_lds();
    } else {
        __syncthreads();
    }

    // gate_up: x, its scales, the table and the pairs are already in this block's LDS
    auto &down_smem = *reinterpret_cast<DownSmem<NUM_TOKENS> *>(smem + SMEM_DOWN_OFFSET);
    const int uwave = __builtin_amdgcn_readfirstlane(tid / THREADS_PER_WARP);
    const auto early_dma = [&] {
        if constexpr (EARLY_DMA<NUM_TOKENS>) {
            // the early slots past gate_up's partial sums, the rest's end below them
            static_assert(SMEM_GATE_UP_OFFSET + SMEM_GATE_UP_SIZE_OF<NUM_TOKENS> <= SMEM_EARLY_SLOTS);
            static_assert(SMEM_DOWN_OFFSET + H_BYTES<NUM_TOKENS> + sizeof(RowsSmem) +
                              (DOWN_STAGED<NUM_TOKENS> - EARLY_SLOTS) * SLOT_BYTES <= SMEM_EARLY_SLOTS);
            // wave w stages slots w, w + WAVES, ..., in straight-line code (every slot is an
            // expert's: a token alone picks TOP_K): with the count of these loads fixed, the last
            // item's waits count past them, so they hold no wave's MFMAs back (and LDS accesses don't
            // wait for them)
            static_assert(EARLY_SLOTS % WAVES == 0 && EARLY_SLOTS < 1 + Config::TOP_K);
#pragma unroll
            for (int k = 0; k < EARLY_SLOTS / WAVES; ++k) {
                const int r = uwave + k * WAVES;
                stage_expert<NUM_TOKENS>(p.down, down_smem, r, __builtin_amdgcn_readfirstlane(table.ids[r]));
            }
        }
    };
    if constexpr (EARLY_DMA<NUM_TOKENS>) {
        gate_up_block<NUM_TOKENS, EARLY0>(x_q, x_s, table, pairs, p.gate_up_weight,
                                          p.gate_up_scale, p.act, smem + SMEM_GATE_UP_OFFSET,
                                          &first, early_dma);
    } else {
        gate_up_block<NUM_TOKENS, EARLY0>(x_q, x_s, table, pairs, p.gate_up_weight,
                                          p.gate_up_scale, p.act, smem + SMEM_GATE_UP_OFFSET,
                                          &first);
    }

    // sync (2), in the slot's SYNC2_PACKET: once every block's h is out, thread t waits for block
    // t's. EARLY_DMA: every wave waits for its h's stores (EPILOGUE4: on every wave; its early DMA
    // ahead of them has landed by then), then an LDS-only sync
    static_assert(EARLY_DMA<NUM_TOKENS> == EPILOGUE4<NUM_TOKENS>);
    const auto publish_h = [&] {
        if constexpr (EARLY_DMA<NUM_TOKENS>) {
            asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
            block_sync_lds();
            if (tid == 0) {
                store_sc1(my_slot + SYNC2_PACKET, uint32x4{0u, 0u, 0u, epoch});
            }
        } else {
            publish(my_slot + SYNC2_PACKET, epoch);
        }
    };
    const auto wait      = [&] { wait_for(slots, SYNC2_PACKET, 0, Config::NUM_BLOCKS, epoch); };
    down_block<NUM_TOKENS>(p.down, table, pairs, down_smem, last_call + 1u, publish_h, wait,
                           prior_bits);
}

} // namespace infera_flash::glm5_m16

// GLM-5's decoder layer after its attention on one TP8 rank for M = 1 .. 4, 6, 8, 12 and 16 tokens,
// MXFP4 experts: the residual stream through post_attention_layernorm, the router's sigmoid top-8 in
// fp32 on the norm's fp32 output (as the op's fp32 reference routes, aklr/router.h), the shared
// expert in the last slot, the expert GEMMs on the output rounded to bf16, then their output summed
// over the ranks of the peer memory in rank order and added to the stream.
// Infera-Flash's persistent kernel (glm5/moe.hip): one block per CU, all 256 resident at once, each
// block swapping its 24 output rows with the same block of every other rank. Every M runs the kernel
// below on glm5_m16/moe.h, which takes up to 16 into each MFMA tile and still reads the weights once,
// on its own state and peer memory, after glm5's; M <= 4 ran glm5's (M16_FROM). It is defined here,
// not in a glm5_m16/moe.hip: the extension names each source's object by its file name alone.
// source: Infera-Flash csrc/glm5 at 3b1dc45
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <ATen/hip/impl/HIPGuardImplMasqueradingAsCUDA.h>
#include <c10/hip/HIPException.h>
#include <optional>
#include <torch/library.h>

#include "glm5/moe.h"
#include "glm5_m16/moe.h"

namespace infera_flash::glm5_m16 {
namespace {

template <int NUM_TOKENS>
__global__ __launch_bounds__(Config::BLOCK_SIZE) __attribute__((amdgpu_waves_per_eu(1, 1))) void
moe_mlp_kernel(const MoeParams p) {
    extern __shared__ __align__(16) uint8_t smem[];
    const uint32_t epoch = next_epoch(static_cast<const uint32x4 *>(p.workspace) +
                                      blockIdx.x * PACKETS_PER_SLOT);
    // the all-reduce's last call number, read now so no wait before the down includes it
    moe_block<NUM_TOKENS>(p, smem, epoch, last_call(p.down.ar));
}

} // namespace
} // namespace infera_flash::glm5_m16

namespace infera_flash {
namespace {

// glm5's state: the blocks' sync slots, then the all-reduce's call number per block; glm5_m16's
// after it: the same, then its sync (1) packets
constexpr int64_t GLM5_STATE_BYTES = WORKSPACE_SIZE + glm5::Config::NUM_BLOCKS * sizeof(int);
constexpr int64_t M16_STATE_BYTES =
    WORKSPACE_SIZE + glm5_m16::Config::NUM_BLOCKS * sizeof(int) + glm5_m16::LOGITS_SIZE;
constexpr int64_t STATE_BYTES = GLM5_STATE_BYTES + M16_STATE_BYTES;
// glm5's receive buffers first, then glm5_m16's: the schema's peer_bytes
constexpr int64_t PEER_BYTES = glm5::Config::AR_BUFFER_SIZE + glm5_m16::Config::AR_BUFFER_SIZE;
// M <= 4 from this many tokens on runs glm5_m16's kernel too, glm5's below it: the same bits, and at
// 1 to 4 tokens 2.2 to 6 us faster (its down weights staged in LDS while the blocks finish gate_up,
// h only of the picked (slot, token) pairs, the fast quant)
constexpr int64_t M16_FROM = 1;

// params: glm5's or glm5_m16's MoeParams; state and recv at that kernel's offsets
template <typename Params>
void fill(Params &p, const at::Tensor &hidden_states, const at::Tensor &norm_weight, double norm_eps,
          const at::Tensor &router_weight, const at::Tensor &correction_bias, const at::Tensor &w1,
          const at::Tensor &w1_scale, const at::Tensor &w2, const at::Tensor &w2_scale,
          double routed_scaling_factor, const at::Tensor &act, at::Tensor &out, uint8_t *state,
          const at::Tensor &peers, int64_t peer_offset, int64_t rank) {
    // the stream itself, no residual to add first
    p.h                     = static_cast<const bfloat16 *>(hidden_states.data_ptr());
    p.gamma                 = static_cast<const bfloat16 *>(norm_weight.data_ptr());
    p.epsilon               = static_cast<float>(norm_eps);
    p.router_weight         = static_cast<const bfloat16 *>(router_weight.data_ptr());
    p.router_bias           = correction_bias.data_ptr<float>();
    p.workspace             = state;
    p.routed_scaling_factor = static_cast<float>(routed_scaling_factor);
    p.gate_up_weight        = static_cast<const uint8_t *>(w1.data_ptr());
    p.gate_up_scale         = w1_scale.data_ptr();
    p.act                   = static_cast<bfloat16 *>(act.data_ptr());
    p.down.h                = p.act;
    p.down.weight           = static_cast<const uint8_t *>(w2.data_ptr());
    p.down.weight_scale     = w2_scale.data_ptr();
    auto &ar                = p.down.ar;
    ar.out                  = static_cast<bfloat16 *>(out.data_ptr());
    ar.accumulate           = true;
    ar.prior                = p.h;
    ar.world                = static_cast<int>(peers.numel());
    ar.rank                 = static_cast<int>(rank);
    ar.calls                = reinterpret_cast<int *>(state + WORKSPACE_SIZE);
    for (int r = 0; r < ar.world; ++r) {
        ar.recv[r] = reinterpret_cast<void *>(peers.data_ptr<int64_t>()[r] + peer_offset);
    }
}

void run(const at::Tensor &hidden_states, const at::Tensor &norm_weight, double norm_eps,
         const at::Tensor &router_weight, const at::Tensor &correction_bias, const at::Tensor &w1,
         const at::Tensor &w1_scale, const at::Tensor &w2, const at::Tensor &w2_scale, int64_t topk,
         int64_t num_expert_group, int64_t topk_group, bool renormalize,
         c10::string_view scoring_func, double routed_scaling_factor,
         std::optional<at::ScalarType> out_dtype, at::Tensor &out, at::Tensor &state,
         const at::Tensor &peers, int64_t rank) {
    const int64_t num_tokens = hidden_states.size(0);
    const bool    m16        = num_tokens > glm5::Config::MAX_NUM_TOKENS || num_tokens >= M16_FROM;
    TORCH_CHECK(((num_tokens >= 1 && num_tokens <= glm5::Config::MAX_NUM_TOKENS) ||
                 num_tokens == 6 || num_tokens == 8 ||
                 num_tokens == 12 || num_tokens == 16) &&
                    topk == glm5::Config::TOP_K && num_expert_group == 1 && topk_group == 1 &&
                    renormalize && scoring_func == "sigmoid",
                "1 to ", glm5::Config::MAX_NUM_TOKENS,
                ", 6, 8, 12 or 16 tokens and GLM-5's routing only");
    // zeroed once and kept: each call counts its epoch and call number on from the last one's
    TORCH_CHECK(state.nbytes() >= STATE_BYTES, "state: ", STATE_BYTES, " bytes");
    // the receive buffers' addresses, read here on the host
    TORCH_CHECK(peers.device().is_cpu() && peers.scalar_type() == at::kLong && peers.dim() == 1 &&
                    peers.numel() >= 1 && peers.numel() <= glm5::Config::MAX_RANKS && rank >= 0 &&
                    rank < peers.numel(),
                "peers: every rank's peer memory, int64 on the host, 1 to ", glm5::Config::MAX_RANKS);
    const at::hip::OptionalHIPGuardMasqueradingAsCUDA guard(hidden_states.device());
    // the blocks wait on each other: all of them must be resident
    int cus = 0;
    C10_HIP_CHECK(hipDeviceGetAttribute(&cus, hipDeviceAttributeMultiprocessorCount,
                                        hidden_states.get_device()));
    TORCH_CHECK(cus == glm5::Config::NUM_BLOCKS, "needs all ", glm5::Config::NUM_BLOCKS,
                " CUs of an MI355X (no partitions)");
    const auto options = hidden_states.options();
    auto      *bytes   = static_cast<uint8_t *>(state.data_ptr());
    const auto stream  = at::hip::getCurrentHIPStream();
    if (!m16) {
        using namespace glm5;
        at::Tensor table = at::empty({static_cast<int64_t>(sizeof(ExpertTable) / sizeof(int))},
                                     options.dtype(at::kInt));
        at::Tensor act =
            at::empty({Config::MAX_SLOTS, Config::MAX_NUM_TOKENS, Config::INTERMEDIATE_SIZE}, options);
        MoeParams p{};
        fill(p, hidden_states, norm_weight, norm_eps, router_weight, correction_bias, w1, w1_scale,
             w2, w2_scale, routed_scaling_factor, act, out, bytes, peers, 0, rank);
        p.table = static_cast<ExpertTable *>(table.data_ptr());
        p.mxfp4 = true;
        moe_launch(p, static_cast<int>(num_tokens), false, stream);
    } else {
        using namespace glm5_m16;
        at::Tensor act = at::empty({MAX_PAIRS, Config::INTERMEDIATE_SIZE}, options);
        MoeParams  p{};
        fill(p, hidden_states, norm_weight, norm_eps, router_weight, correction_bias, w1, w1_scale,
             w2, w2_scale, routed_scaling_factor, act, out, bytes + GLM5_STATE_BYTES, peers,
             glm5::Config::AR_BUFFER_SIZE, rank);
        p.logits = reinterpret_cast<uint32x4 *>(bytes + GLM5_STATE_BYTES + WORKSPACE_SIZE +
                                                Config::NUM_BLOCKS * sizeof(int));
        // all of a CU's LDS: one block per CU
        const auto kernel = num_tokens == 1    ? moe_mlp_kernel<1>
                            : num_tokens == 2  ? moe_mlp_kernel<2>
                            : num_tokens == 3  ? moe_mlp_kernel<3>
                            : num_tokens == 4  ? moe_mlp_kernel<4>
                            : num_tokens == 6  ? moe_mlp_kernel<6>
                            : num_tokens == 8  ? moe_mlp_kernel<8>
                            : num_tokens == 12 ? moe_mlp_kernel<12>
                                               : moe_mlp_kernel<16>;
        kernel<<<Config::NUM_BLOCKS, Config::BLOCK_SIZE, Config::SMEM_SIZE, stream>>>(p);
        C10_HIP_CHECK(hipGetLastError());
    }
}

